                        +(PA_0 - PQ[a0])*(delta[b0][b1]*delta[c0][c1]*delta[d0][d1]*delta[g0][g1] + delta[b0][b1]*delta[c0][d0]*delta[c1][d1]*delta[g0][g1] + delta[b0][b1]*delta[c0][d1]*delta[c1][d0]*delta[g0][g1]) + (PA_x - PQ[g0])*(delta[a0][g1]*delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g1]*delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g1]*delta[b0][b1]*delta[c0][d1]*delta[c1][d0]) + (PA_y - PQ[g1])*(delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[c1][d0])

                        -QC_0*(delta[a0][b0]*delta[b1][c1]*delta[d0][d1]*delta[g0][g1] + delta[a0][b0]*delta[b1][d0]*delta[c1][d1]*delta[g0][g1] + delta[a0][b0]*delta[b1][d1]*delta[c1][d0]*delta[g0][g1] + delta[a0][b1]*delta[b0][c1]*delta[d0][d1]*delta[g0][g1] + delta[a0][b1]*delta[b0][d0]*delta[c1][d1]*delta[g0][g1] + delta[a0][b1]*delta[b0][d1]*delta[c1][d0]*delta[g0][g1] + delta[a0][c1]*delta[b0][b1]*delta[d0][d1]*delta[g0][g1] + delta[a0][d0]*delta[b0][b1]*delta[c1][d1]*delta[g0][g1] + delta[a0][d1]*delta[b0][b1]*delta[c1][d0]*delta[g0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c1][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c1][d1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c1][g1]*delta[d0][d1] + delta[a0][g0]*delta[b0][c1]*delta[b1][g1]*delta[d0][d1] + delta[a0][g0]*delta[b0][d0]*delta[b1][g1]*delta[c1][d1] + delta[a0][g0]*delta[b0][d1]*delta[b1][g1]*delta[c1][d0] + delta[a0][g0]*delta[b0][g1]*delta[b1][c1]*delta[d0][d1] + delta[a0][g0]*delta[b0][g1]*delta[b1][d0]*delta[c1][d1] + delta[a0][g0]*delta[b0][g1]*delta[b1][d1]*delta[c1][d0] + delta[a0][g1]*delta[b0][b1]*delta[c1][d0]*delta[d1][g0] + delta[a0][g1]*delta[b0][b1]*delta[c1][d1]*delta[d0][g0] + delta[a0][g1]*delta[b0][b1]*delta[c1][g0]*delta[d0][d1] + delta[a0][g1]*delta[b0][c1]*delta[b1][g0]*delta[d0][d1] + delta[a0][g1]*delta[b0][d0]*delta[b1][g0]*delta[c1][d1] + delta[a0][g1]*delta[b0][d1]*delta[b1][g0]*delta[c1][d0] + delta[a0][g1]*delta[b0][g0]*delta[b1][c1]*delta[d0][d1] + delta[a0][g1]*delta[b0][g0]*delta[b1][d0]*delta[c1][d1] + delta[a0][g1]*delta[b0][g0]*delta[b1][d1]*delta[c1][d0]) - QC_1*(delta[a0][b0]*delta[b1][c0]*delta[d0][d1]*delta[g0][g1] + delta[a0][b0]*delta[b1][d0]*delta[c0][d1]*delta[g0][g1] + delta[a0][b0]*delta[b1][d1]*delta[c0][d0]*delta[g0][g1] + delta[a0][b1]*delta[b0][c0]*delta[d0][d1]*delta[g0][g1] + delta[a0][b1]*delta[b0][d0]*delta[c0][d1]*delta[g0][g1] + delta[a0][b1]*delta[b0][d1]*delta[c0][d0]*delta[g0][g1] + delta[a0][c0]*delta[b0][b1]*delta[d0][d1]*delta[g0][g1] + delta[a0][d0]*delta[b0][b1]*delta[c0][d1]*delta[g0][g1] + delta[a0][d1]*delta[b0][b1]*delta[c0][d0]*delta[g0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[d0][d1] + delta[a0][g0]*delta[b0][c0]*delta[b1][g1]*delta[d0][d1] + delta[a0][g0]*delta[b0][d0]*delta[b1][g1]*delta[c0][d1] + delta[a0][g0]*delta[b0][d1]*delta[b1][g1]*delta[c0][d0] + delta[a0][g0]*delta[b0][g1]*delta[b1][c0]*delta[d0][d1] + delta[a0][g0]*delta[b0][g1]*delta[b1][d0]*delta[c0][d1] + delta[a0][g0]*delta[b0][g1]*delta[b1][d1]*delta[c0][d0] + delta[a0][g1]*delta[b0][b1]*delta[c0][d0]*delta[d1][g0] + delta[a0][g1]*delta[b0][b1]*delta[c0][d1]*delta[d0][g0] + delta[a0][g1]*delta[b0][b1]*delta[c0][g0]*delta[d0][d1] + delta[a0][g1]*delta[b0][c0]*delta[b1][g0]*delta[d0][d1] + delta[a0][g1]*delta[b0][d0]*delta[b1][g0]*delta[c0][d1] + delta[a0][g1]*delta[b0][d1]*delta[b1][g0]*delta[c0][d0] + delta[a0][g1]*delta[b0][g0]*delta[b1][c0]*delta[d0][d1] + delta[a0][g1]*delta[b0][g0]*delta[b1][d0]*delta[c0][d1] + delta[a0][g1]*delta[b0][g0]*delta[b1][d1]*delta[c0][d0]) - QD_0*(delta[a0][b0]*delta[b1][c0]*delta[c1][d1]*delta[g0][g1] + delta[a0][b0]*delta[b1][c1]*delta[c0][d1]*delta[g0][g1] + delta[a0][b0]*delta[b1][d1]*delta[c0][c1]*delta[g0][g1] + delta[a0][b1]*delta[b0][c0]*delta[c1][d1]*delta[g0][g1] + delta[a0][b1]*delta[b0][c1]*delta[c0][d1]*delta[g0][g1] + delta[a0][b1]*delta[b0][d1]*delta[c0][c1]*delta[g0][g1] + delta[a0][c0]*delta[b0][b1]*delta[c1][d1]*delta[g0][g1] + delta[a0][c1]*delta[b0][b1]*delta[c0][d1]*delta[g0][g1] + delta[a0][d1]*delta[b0][b1]*delta[c0][c1]*delta[g0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[c1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[c1][d1] + delta[a0][g0]*delta[b0][c0]*delta[b1][g1]*delta[c1][d1] + delta[a0][g0]*delta[b0][c1]*delta[b1][g1]*delta[c0][d1] + delta[a0][g0]*delta[b0][d1]*delta[b1][g1]*delta[c0][c1] + delta[a0][g0]*delta[b0][g1]*delta[b1][c0]*delta[c1][d1] + delta[a0][g0]*delta[b0][g1]*delta[b1][c1]*delta[c0][d1] + delta[a0][g0]*delta[b0][g1]*delta[b1][d1]*delta[c0][c1] + delta[a0][g1]*delta[b0][b1]*delta[c0][c1]*delta[d1][g0] + delta[a0][g1]*delta[b0][b1]*delta[c0][d1]*delta[c1][g0] + delta[a0][g1]*delta[b0][b1]*delta[c0][g0]*delta[c1][d1] + delta[a0][g1]*delta[b0][c0]*delta[b1][g0]*delta[c1][d1] + delta[a0][g1]*delta[b0][c1]*delta[b1][g0]*delta[c0][d1] + delta[a0][g1]*delta[b0][d1]*delta[b1][g0]*delta[c0][c1] + delta[a0][g1]*delta[b0][g0]*delta[b1][c0]*delta[c1][d1] + delta[a0][g1]*delta[b0][g0]*delta[b1][c1]*delta[c0][d1] + delta[a0][g1]*delta[b0][g0]*delta[b1][d1]*delta[c0][c1]) - QD_1*(delta[a0][b0]*delta[b1][c0]*delta[c1][d0]*delta[g0][g1] + delta[a0][b0]*delta[b1][c1]*delta[c0][d0]*delta[g0][g1] + delta[a0][b0]*delta[b1][d0]*delta[c0][c1]*delta[g0][g1] + delta[a0][b1]*delta[b0][c0]*delta[c1][d0]*delta[g0][g1] + delta[a0][b1]*delta[b0][c1]*delta[c0][d0]*delta[g0][g1] + delta[a0][b1]*delta[b0][d0]*delta[c0][c1]*delta[g0][g1] + delta[a0][c0]*delta[b0][b1]*delta[c1][d0]*delta[g0][g1] + delta[a0][c1]*delta[b0][b1]*delta[c0][d0]*delta[g0][g1] + delta[a0][d0]*delta[b0][b1]*delta[c0][c1]*delta[g0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[c1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[c1][d0] + delta[a0][g0]*delta[b0][c0]*delta[b1][g1]*delta[c1][d0] + delta[a0][g0]*delta[b0][c1]*delta[b1][g1]*delta[c0][d0] + delta[a0][g0]*delta[b0][d0]*delta[b1][g1]*delta[c0][c1] + delta[a0][g0]*delta[b0][g1]*delta[b1][c0]*delta[c1][d0] + delta[a0][g0]*delta[b0][g1]*delta[b1][c1]*delta[c0][d0] + delta[a0][g0]*delta[b0][g1]*delta[b1][d0]*delta[c0][c1] + delta[a0][g1]*delta[b0][b1]*delta[c0][c1]*delta[d0][g0] + delta[a0][g1]*delta[b0][b1]*delta[c0][d0]*delta[c1][g0] + delta[a0][g1]*delta[b0][b1]*delta[c0][g0]*delta[c1][d0] + delta[a0][g1]*delta[b0][c0]*delta[b1][g0]*delta[c1][d0] + delta[a0][g1]*delta[b0][c1]*delta[b1][g0]*delta[c0][d0] + delta[a0][g1]*delta[b0][d0]*delta[b1][g0]*delta[c0][c1] + delta[a0][g1]*delta[b0][g0]*delta[b1][c0]*delta[c1][d0] + delta[a0][g1]*delta[b0][g0]*delta[b1][c1]*delta[c0][d0] + delta[a0][g1]*delta[b0][g0]*delta[b1][d0]*delta[c0][c1])

                    )

                    + F9_t[1] * (-1.0) * inv_S2 * inv_S2 * inv_S4 * a_i * a_i * (

                        +PA_0*PA_x*PA_y*(delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[b0][b1]*delta[c0][d1]*delta[c1][d0]) + PA_0*PA_x*PB_0*(delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[b1][g1]*delta[c0][d1]*delta[c1][d0]) + PA_0*PA_x*PB_1*(delta[b0][g1]*delta[c0][c1]*delta[d0][d1] + delta[b0][g1]*delta[c0][d0]*delta[c1][d1] + delta[b0][g1]*delta[c0][d1]*delta[c1][d0]) + PA_0*PA_y*PB_0*(delta[b1][g0]*delta[c0][c1]*delta[d0][d1] + delta[b1][g0]*delta[c0][d0]*delta[c1][d1] + delta[b1][g0]*delta[c0][d1]*delta[c1][d0]) + PA_0*PA_y*PB_1*(delta[b0][g0]*delta[c0][c1]*delta[d0][d1] + delta[b0][g0]*delta[c0][d0]*delta[c1][d1] + delta[b0][g0]*delta[c0][d1]*delta[c1][d0]) + PA_0*PB_0*PB_1*(delta[c0][c1]*delta[d0][d1]*delta[g0][g1] + delta[c0][d0]*delta[c1][d1]*delta[g0][g1] + delta[c0][d1]*delta[c1][d0]*delta[g0][g1]) + PA_x*PA_y*PB_0*(delta[a0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][b1]*delta[c0][d1]*delta[c1][d0]) + PA_x*PA_y*PB_1*(delta[a0][b0]*delta[c0][c1]*delta[d0][d1] + delta[a0][b0]*delta[c0][d0]*delta[c1][d1] + delta[a0][b0]*delta[c0][d1]*delta[c1][d0]) + PA_x*PB_0*PB_1*(delta[a0][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g1]*delta[c0][d1]*delta[c1][d0]) + PA_y*PB_0*PB_1*(delta[a0][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[c0][d1]*delta[c1][d0])

                    )

                    + F9_t[1] * 0.5 * inv_S2 * inv_S2 * inv_S4 * a_i * (

                        +PB_0*(delta[a0][b1]*delta[c0][c1]*delta[d0][d1]*delta[g0][g1] + delta[a0][b1]*delta[c0][d0]*delta[c1][d1]*delta[g0][g1] + delta[a0][b1]*delta[c0][d1]*delta[c1][d0]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b1][g1]*delta[c0][d1]*delta[c1][d0] + delta[a0][g1]*delta[b1][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][g1]*delta[b1][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][g1]*delta[b1][g0]*delta[c0][d1]*delta[c1][d0]) + PB_1*(delta[a0][b0]*delta[c0][c1]*delta[d0][d1]*delta[g0][g1] + delta[a0][b0]*delta[c0][d0]*delta[c1][d1]*delta[g0][g1] + delta[a0][b0]*delta[c0][d1]*delta[c1][d0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b0][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b0][g1]*delta[c0][d1]*delta[c1][d0] + delta[a0][g1]*delta[b0][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][g1]*delta[b0][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][g1]*delta[b0][g0]*delta[c0][d1]*delta[c1][d0])

                        +PA_0*(delta[b0][b1]*delta[c0][c1]*delta[d0][d1]*delta[g0][g1] + delta[b0][b1]*delta[c0][d0]*delta[c1][d1]*delta[g0][g1] + delta[b0][b1]*delta[c0][d1]*delta[c1][d0]*delta[g0][g1]) + PA_x*(delta[a0][g1]*delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g1]*delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g1]*delta[b0][b1]*delta[c0][d1]*delta[c1][d0]) + PA_y*(delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[c1][d0])

                    )

                    + F9_t[1] * (-2.0) * S1 * inv_S2 * inv_S2 * inv_S4 * a_i * a_i * (

                        +PA_0*PA_x*PA_y*PB_0*PB_1*(delta[c0][c1]*delta[d0][d1] + delta[c0][d0]*delta[c1][d1] + delta[c0][d1]*delta[c1][d0])

                    )


                );

        ERIs[threadIdx.y][threadIdx.x] += eri_ijkl * dd_mat_D[kl] * kl_factor;

    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < pd_prim_pair_count_local))
    {
        double hess_ii_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM; n++)
        {
            hess_ii_xy += ERIs[n][threadIdx.x];
        }

        atomicAdd(hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + i], hess_ii_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }
}

__global__ void __launch_bounds__(TILE_SIZE_J)
computeCoulombHessianPDDD_II_2(double*         hess_xy,
                               const uint32_t  hess_cart_ind_0,
                               const uint32_t  hess_cart_ind_1,
                               const double    prefac_coulomb,
                               const double*   p_prim_info,
                               const uint32_t  p_prim_count,
                               const double*   d_prim_info,
                               const uint32_t  d_prim_count,
                               const double*   pd_mat_D_local,
                               const double*   dd_mat_D,
                               const double*   pd_mat_Q_local,
                               const double*   dd_mat_Q,
                               const uint32_t* pd_first_inds_local,
                               const uint32_t* pd_second_inds_local,
                               const double*   pd_pair_data_local,
                               const uint32_t  pd_prim_pair_count_local,
                               const uint32_t* dd_first_inds,
                               const uint32_t* dd_second_inds,
                               const double*   dd_pair_data,
                               const uint32_t  dd_prim_pair_count,
                               const uint32_t* prim_cart_ao_to_atom_inds,
                               const uint32_t  s_prim_count,
                               const double*   boys_func_table,
                               const double*   boys_func_ft,
                               const double    eri_threshold)
{
    // each thread row scans over [ij|??] and sum up to a primitive J matrix element
    // J. Chem. Theory Comput. 2009, 5, 4, 1004-1015

    __shared__ double   ERIs[TILE_DIM][TILE_DIM + 1];
    __shared__ uint32_t d_cart_inds[6][2];
    __shared__ double   delta[3][3];
    __shared__ uint32_t g0, g1;

    const uint32_t ij = blockDim.x * blockIdx.x + threadIdx.x;

    double a_i, a_j, r_i[3], r_j[3], S_ij_00, S1, inv_S1, ij_factor_D;
    double PA_0, PB_0, PB_1, PA_x, PA_y;
    uint32_t i, j, a0, b0, b1;

    ERIs[threadIdx.y][threadIdx.x] = 0.0;

    if ((threadIdx.y == 0) && (threadIdx.x == 0))
    {
        d_cart_inds[0][0] = 0; d_cart_inds[0][1] = 0;
        d_cart_inds[1][0] = 0; d_cart_inds[1][1] = 1;
        d_cart_inds[2][0] = 0; d_cart_inds[2][1] = 2;
        d_cart_inds[3][0] = 1; d_cart_inds[3][1] = 1;
        d_cart_inds[4][0] = 1; d_cart_inds[4][1] = 2;
        d_cart_inds[5][0] = 2; d_cart_inds[5][1] = 2;

        delta[0][0] = 1.0; delta[0][1] = 0.0; delta[0][2] = 0.0;
        delta[1][0] = 0.0; delta[1][1] = 1.0; delta[1][2] = 0.0;
        delta[2][0] = 0.0; delta[2][1] = 0.0; delta[2][2] = 1.0;

        g0 = hess_cart_ind_0;
        g1 = hess_cart_ind_1;
    }

    __syncthreads();

    if (ij < pd_prim_pair_count_local)
    {
        i = pd_first_inds_local[ij];
        j = pd_second_inds_local[ij];

        a_i = p_prim_info[i / 3 + p_prim_count * 0];

        r_i[0] = p_prim_info[i / 3 + p_prim_count * 2];
        r_i[1] = p_prim_info[i / 3 + p_prim_count * 3];
        r_i[2] = p_prim_info[i / 3 + p_prim_count * 4];

        a_j = d_prim_info[j / 6 + d_prim_count * 0];

        r_j[0] = d_prim_info[j / 6 + d_prim_count * 2];
        r_j[1] = d_prim_info[j / 6 + d_prim_count * 3];
        r_j[2] = d_prim_info[j / 6 + d_prim_count * 4];

        S1 = a_i + a_j;
        inv_S1 = 1.0 / S1;

        S_ij_00 = pd_pair_data_local[ij];

        ij_factor_D = 2.0 * pd_mat_D_local[ij];

