delta[c1][d0] + delta[a0][g0]*delta[b0][c1]*delta[c0][d0] + delta[a0][g0]*delta[b0][d0]*delta[c0][c1])

                        +delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*(-PA_y*PQ[d0]*PQ[d1] - PA_y*PQ[d0]*QD_1 - PA_y*PQ[d1]*QD_0) + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*(-PA_y*PQ[c1]*PQ[d1] - PA_y*PQ[c1]*QD_1 - PA_y*PQ[d1]*QC_1) + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*(-PA_y*PQ[c1]*PQ[d0] - PA_y*PQ[c1]*QD_0 - PA_y*PQ[d0]*QC_1) + delta[a0][g0]*delta[b0][b1]*delta[c1][d0]*(-PA_y*PQ[c0]*PQ[d1] - PA_y*PQ[c0]*QD_1 - PA_y*PQ[d1]*QC_0) + delta[a0][g0]*delta[b0][b1]*delta[c1][d1]*(-PA_y*PQ[c0]*PQ[d0] - PA_y*PQ[c0]*QD_0 - PA_y*PQ[d0]*QC_0) + delta[a0][g0]*delta[b0][b1]*delta[d0][d1]*(-PA_y*PQ[c0]*PQ[c1] - PA_y*PQ[c0]*QC_1 - PA_y*PQ[c1]*QC_0) + delta[a0][g1]*delta[b0][b1]*delta[c0][c1]*(-PA_x*PQ[d0]*PQ[d1] - PA_x*PQ[d0]*QD_1 - PA_x*PQ[d1]*QD_0) + delta[a0][g1]*delta[b0][b1]*delta[c0][d0]*(-PA_x*PQ[c1]*PQ[d1] - PA_x*PQ[c1]*QD_1 - PA_x*PQ[d1]*QC_1) + delta[a0][g1]*delta[b0][b1]*delta[c0][d1]*(-PA_x*PQ[c1]*PQ[d0] - PA_x*PQ[c1]*QD_0 - PA_x*PQ[d0]*QC_1) + delta[a0][g1]*delta[b0][b1]*delta[c1][d0]*(-PA_x*PQ[c0]*PQ[d1] - PA_x*PQ[c0]*QD_1 - PA_x*PQ[d1]*QC_0) + delta[a0][g1]*delta[b0][b1]*delta[c1][d1]*(-PA_x*PQ[c0]*PQ[d0] - PA_x*PQ[c0]*QD_0 - PA_x*PQ[d0]*QC_0) + delta[a0][g1]*delta[b0][b1]*delta[d0][d1]*(-PA_x*PQ[c0]*PQ[c1] - PA_x*PQ[c0]*QC_1 - PA_x*PQ[c1]*QC_0) + delta[b0][b1]*delta[c0][c1]*delta[g0][g1]*(-PA_0*PQ[d0]*PQ[d1] - PA_0*PQ[d0]*QD_1 - PA_0*PQ[d1]*QD_0) + delta[b0][b1]*delta[c0][d0]*delta[g0][g1]*(-PA_0*PQ[c1]*PQ[d1] - PA_0*PQ[c1]*QD_1 - PA_0*PQ[d1]*QC_1) + delta[b0][b1]*delta[c0][d1]*delta[g0][g1]*(-PA_0*PQ[c1]*PQ[d0] - PA_0*PQ[c1]*QD_0 - PA_0*PQ[d0]*QC_1) + delta[b0][b1]*delta[c1][d0]*delta[g0][g1]*(-PA_0*PQ[c0]*PQ[d1] - PA_0*PQ[c0]*QD_1 - PA_0*PQ[d1]*QC_0) + delta[b0][b1]*delta[c1][d1]*delta[g0][g1]*(-PA_0*PQ[c0]*PQ[d0] - PA_0*PQ[c0]*QD_0 - PA_0*PQ[d0]*QC_0) + delta[b0][b1]*delta[d0][d1]*delta[g0][g1]*(-PA_0*PQ[c0]*PQ[c1] - PA_0*PQ[c0]*QC_1 - PA_0*PQ[c1]*QC_0)

                        +(PB_0*PB_1*PQ[c0] + PB_0*PB_1*QC_0)*(delta[a0][c1]*delta[d0][d1]*delta[g0][g1] + delta[a0][d0]*delta[c1][d1]*delta[g0][g1] + delta[a0][d1]*delta[c1][d0]*delta[g0][g1] + delta[a0][g0]*delta[c1][d0]*delta[d1][g1] + delta[a0][g0]*delta[c1][d1]*delta[d0][g1] + delta[a0][g0]*delta[c1][g1]*delta[d0][d1] + delta[a0][g1]*delta[c1][d0]*delta[d1][g0] + delta[a0][g1]*delta[c1][d1]*delta[d0][g0] + delta[a0][g1]*delta[c1][g0]*delta[d0][d1]) + (PB_0*PB_1*PQ[c1] + PB_0*PB_1*QC_1)*(delta[a0][c0]*delta[d0][d1]*delta[g0][g1] + delta[a0][d0]*delta[c0][d1]*delta[g0][g1] + delta[a0][d1]*delta[c0][d0]*delta[g0][g1] + delta[a0][g0]*delta[c0][d0]*delta[d1][g1] + delta[a0][g0]*delta[c0][d1]*delta[d0][g1] + delta[a0][g0]*delta[c0][g1]*delta[d0][d1] + delta[a0][g1]*delta[c0][d0]*delta[d1][g0] + delta[a0][g1]*delta[c0][d1]*delta[d0][g0] + delta[a0][g1]*delta[c0][g0]*delta[d0][d1]) + (PB_0*PB_1*PQ[d0] + PB_0*PB_1*QD_0)*(delta[a0][c0]*delta[c1][d1]*delta[g0][g1] + delta[a0][c1]*delta[c0][d1]*delta[g0][g1] + delta[a0][d1]*delta[c0][c1]*delta[g0][g1] + delta[a0][g0]*delta[c0][c1]*delta[d1][g1] + delta[a0][g0]*delta[c0][d1]*delta[c1][g1] + delta[a0][g0]*delta[c0][g1]*delta[c1][d1] + delta[a0][g1]*delta[c0][c1]*delta[d1][g0] + delta[a0][g1]*delta[c0][d1]*delta[c1][g0] + delta[a0][g1]*delta[c0][g0]*delta[c1][d1]) + (PB_0*PB_1*PQ[d1] + PB_0*PB_1*QD_1)*(delta[a0][c0]*delta[c1][d0]*delta[g0][g1] + delta[a0][c1]*delta[c0][d0]*delta[g0][g1] + delta[a0][d0]*delta[c0][c1]*delta[g0][g1] + delta[a0][g0]*delta[c0][c1]*delta[d0][g1] + delta[a0][g0]*delta[c0][d0]*delta[c1][g1] + delta[a0][g0]*delta[c0][g1]*delta[c1][d0] + delta[a0][g1]*delta[c0][c1]*delta[d0][g0] + delta[a0][g1]*delta[c0][d0]*delta[c1][g0] + delta[a0][g1]*delta[c0][g0]*delta[c1][d0])

                        +(-PB_0*PQ[c0]*PQ[c1] - PB_0*PQ[c0]*QC_1 - PB_0*PQ[c1]*QC_0)*(delta[a0][b1]*delta[d0][d1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1]*delta[d0][d1] + delta[a0][g1]*delta[b1][g0]*delta[d0][d1]) + (-PB_0*PQ[c0]*PQ[d0] - PB_0*PQ[c0]*QD_0 - PB_0*PQ[d0]*QC_0)*(delta[a0][b1]*delta[c1][d1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1]*delta[c1][d1] + delta[a0][g1]*delta[b1][g0]*delta[c1][d1]) + (-PB_0*PQ[c0]*PQ[d1] - PB_0*PQ[c0]*QD_1 - PB_0*PQ[d1]*QC_0)*(delta[a0][b1]*delta[c1][d0]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1]*delta[c1][d0] + delta[a0][g1]*delta[b1][g0]*delta[c1][d0]) + (-PB_0*PQ[c1]*PQ[d0] - PB_0*PQ[c1]*QD_0 - PB_0*PQ[d0]*QC_1)*(delta[a0][b1]*delta[c0][d1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1]*delta[c0][d1] + delta[a0][g1]*delta[b1][g0]*delta[c0][d1]) + (-PB_0*PQ[c1]*PQ[d1] - PB_0*PQ[c1]*QD_1 - PB_0*PQ[d1]*QC_1)*(delta[a0][b1]*delta[c0][d0]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1]*delta[c0][d0] + delta[a0][g1]*delta[b1][g0]*delta[c0][d0]) + (-PB_0*PQ[d0]*PQ[d1] - PB_0*PQ[d0]*QD_1 - PB_0*PQ[d1]*QD_0)*(delta[a0][b1]*delta[c0][c1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1]*delta[c0][c1] + delta[a0][g1]*delta[b1][g0]*delta[c0][c1]) + (-PB_1*PQ[c0]*PQ[c1] - PB_1*PQ[c0]*QC_1 - PB_1*PQ[c1]*QC_0)*(delta[a0][b0]*delta[d0][d1]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1]*delta[d0][d1] + delta[a0][g1]*delta[b0][g0]*delta[d0][d1]) + (-PB_1*PQ[c0]*PQ[d0] - PB_1*PQ[c0]*QD_0 - PB_1*PQ[d0]*QC_0)*(delta[a0][b0]*delta[c1][d1]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1]*delta[c1][d1] + delta[a0][g1]*delta[b0][g0]*delta[c1][d1]) + (-PB_1*PQ[c0]*PQ[d1] - PB_1*PQ[c0]*QD_1 - PB_1*PQ[d1]*QC_0)*(delta[a0][b0]*delta[c1][d0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1]*delta[c1][d0] + delta[a0][g1]*delta[b0][g0]*delta[c1][d0]) + (-PB_1*PQ[c1]*PQ[d0] - PB_1*PQ[c1]*QD_0 - PB_1*PQ[d0]*QC_1)*(delta[a0][b0]*delta[c0][d1]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1]*delta[c0][d1] + delta[a0][g1]*delta[b0][g0]*delta[c0][d1]) + (-PB_1*PQ[c1]*PQ[d1] - PB_1*PQ[c1]*QD_1 - PB_1*PQ[d1]*QC_1)*(delta[a0][b0]*delta[c0][d0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1]*delta[c0][d0] + delta[a0][g1]*delta[b0][g0]*delta[c0][d0]) + (-PB_1*PQ[d0]*PQ[d1] - PB_1*PQ[d0]*QD_1 - PB_1*PQ[d1]*QD_0)*(delta[a0][b0]*delta[c0][c1]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1]*delta[c0][c1] + delta[a0][g1]*delta[b0][g0]*delta[c0][c1])

