a[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1])*(-PQ[a0]*PQ[c0]*PQ[c1]*PQ[g1]*QD_0 - PQ[a0]*PQ[c0]*PQ[d0]*PQ[g1]*QC_1 - PQ[a0]*PQ[c1]*PQ[d0]*PQ[g1]*QC_0) + (delta[b0][b1]*delta[d1][g1] + delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1])*(-PQ[a0]*PQ[c0]*PQ[c1]*PQ[g0]*QD_0 - PQ[a0]*PQ[c0]*PQ[d0]*PQ[g0]*QC_1 - PQ[a0]*PQ[c1]*PQ[d0]*PQ[g0]*QC_0) + (delta[b0][c0]*delta[g0][g1] + delta[b0][g0]*delta[c0][g1] + delta[b0][g1]*delta[c0][g0])*(-PQ[a0]*PQ[b1]*PQ[c1]*PQ[d0]*QD_1 - PQ[a0]*PQ[b1]*PQ[c1]*PQ[d1]*QD_0 - PQ[a0]*PQ[b1]*PQ[d0]*PQ[d1]*QC_1) + (delta[b0][c1]*delta[g0][g1] + delta[b0][g0]*delta[c1][g1] + delta[b0][g1]*delta[c1][g0])*(-PQ[a0]*PQ[b1]*PQ[c0]*PQ[d0]*QD_1 - PQ[a0]*PQ[b1]*PQ[c0]*PQ[d1]*QD_0 - PQ[a0]*PQ[b1]*PQ[d0]*PQ[d1]*QC_0) + (delta[b0][d0]*delta[g0][g1] + delta[b0][g0]*delta[d0][g1] + delta[b0][g1]*delta[d0][g0])*(-PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1]*QD_1 - PQ[a0]*PQ[b1]*PQ[c0]*PQ[d1]*QC_1 - PQ[a0]*PQ[b1]*PQ[c1]*PQ[d1]*QC_0) + (delta[b0][d1]*delta[g0][g1] + delta[b0][g0]*delta[d1][g1] + delta[b0][g1]*delta[d1][g0])*(-PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1]*QD_0 - PQ[a0]*PQ[b1]*PQ[c0]*PQ[d0]*QC_1 - PQ[a0]*PQ[b1]*PQ[c1]*PQ[d0]*QC_0) + (delta[b1][c0]*delta[g0][g1] + delta[b1][g0]*delta[c0][g1] + delta[b1][g1]*delta[c0][g0])*(-PQ[a0]*PQ[b0]*PQ[c1]*PQ[d0]*QD_1 - PQ[a0]*PQ[b0]*PQ[c1]*PQ[d1]*QD_0 - PQ[a0]*PQ[b0]*PQ[d0]*PQ[d1]*QC_1) + (delta[b1][c1]*delta[g0][g1] + delta[b1][g0]*delta[c1][g1] + delta[b1][g1]*delta[c1][g0])*(-PQ[a0]*PQ[b0]*PQ[c0]*PQ[d0]*QD_1 - PQ[a0]*PQ[b0]*PQ[c0]*PQ[d1]*QD_0 - PQ[a0]*PQ[b0]*PQ[d0]*PQ[d1]*QC_0) + (delta[b1][d0]*delta[g0][g1] + delta[b1][g0]*delta[d0][g1] + delta[b1][g1]*delta[d0][g0])*(-PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*QD_1 - PQ[a0]*PQ[b0]*PQ[c0]*PQ[d1]*QC_1 - PQ[a0]*PQ[b0]*PQ[c1]*PQ[d1]*QC_0) + (delta[b1][d1]*delta[g0][g1] + delta[b1][g0]*delta[d1][g1] + delta[b1][g1]*delta[d1][g0])*(-PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*QD_0 - PQ[a0]*PQ[b0]*PQ[c0]*PQ[d0]*QC_1 - PQ[a0]*PQ[b0]*PQ[c1]*PQ[d0]*QC_0)

                        +(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])*(-PQ[c0]*PQ[c1]*PQ[d0]*PQ[g1]*QD_1 - PQ[c0]*PQ[c1]*PQ[d1]*PQ[g1]*QD_0 - PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]*QC_1 - PQ[c1]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0) + (delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1])*(-PQ[c0]*PQ[c1]*PQ[d0]*PQ[g0]*QD_1 - PQ[c0]*PQ[c1]*PQ[d1]*PQ[g0]*QD_0 - PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]*QC_1 - PQ[c1]*PQ[d0]*PQ[d1]*PQ[g0]*QC_0) + (delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0])*(-PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 - PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 - PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 - PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0) + (delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0])*(-PQ[b0]*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 - PQ[b0]*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 - PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 - PQ[b0]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0) + (delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])*(-PQ[a0]*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 - PQ[a0]*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 - PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 - PQ[a0]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0)

                    )


                );

        ERIs[threadIdx.y][threadIdx.x] += eri_ijkl * dd_mat_D[kl] * kl_factor;

    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < pd_prim_pair_count_local))
    {
        double hess_ii_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM; n++)
        {
            hess_ii_xy += ERIs[n][threadIdx.x];
        }

        atomicAdd(hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + i], hess_ii_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }
