                    )

                    + F9_t[6] * 2.0 * S1 * S1 * S1 * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * (

                        +delta[a0][g0]*(PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[g1]*QD_1 + PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*PQ[g1]*QD_0 + PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]*QC_1 + PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0) + delta[a0][g1]*(PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[g0]*QD_1 + PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*PQ[g0]*QD_0 + PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]*QC_1 + PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g0]*QC_0) + delta[g0][g1]*(PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 + PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 + PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 + PQ[a0]*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0)

                    )

                    + F9_t[6] * 4.0 * S1 * S1 * S2 * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * a_i * (

                        +PA_0*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g0]*PQ[g1]*QD_0*QD_1 + PA_0*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[g0]*PQ[g1]*QC_1*QD_1 + PA_0*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d1]*PQ[g0]*PQ[g1]*QC_1*QD_0 + PA_0*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g0]*PQ[g1]*QC_0*QD_1 + PA_0*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g0]*PQ[g1]*QC_0*QD_0 + PA_0*PQ[b0]*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1]*QC_0*QC_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g1]*QD_0*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[g1]*QC_1*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d1]*PQ[g1]*QC_1*QD_0 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g1]*QC_0*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g1]*QC_0*QD_0 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0*QC_1 + PA_y*PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g0]*QD_0*QD_1 + PA_y*PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[g0]*QC_1*QD_1 + PA_y*PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d1]*PQ[g0]*QC_1*QD_0 + PA_y*PQ[a0]*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g0]*QC_0*QD_1 + PA_y*PQ[a0]*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g0]*QC_0*QD_0 + PA_y*PQ[a0]*PQ[b0]*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g0]*QC_0*QC_1 + PB_0*PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g0]*PQ[g1]*QD_0*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[g0]*PQ[g1]*QC_1*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[c0]*PQ[d1]*PQ[g0]*PQ[g1]*QC_1*QD_0 + PB_0*PQ[a0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g0]*PQ[g1]*QC_0*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g0]*PQ[g1]*QC_0*QD_0 + PB_0*PQ[a0]*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1]*QC_0*QC_1 + PB_1*PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*PQ[g0]*PQ[g1]*QD_0*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[c0]*PQ[d0]*PQ[g0]*PQ[g1]*QC_1*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[c0]*PQ[d1]*PQ[g0]*PQ[g1]*QC_1*QD_0 + PB_1*PQ[a0]*PQ[b0]*PQ[c1]*PQ[d0]*PQ[g0]*PQ[g1]*QC_0*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[c1]*PQ[d1]*PQ[g0]*PQ[g1]*QC_0*QD_0 + PB_1*PQ[a0]*PQ[b0]*PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1]*QC_0*QC_1

                    )

                    + F9_t[6] * 4.0 * S1 * S2 * S2 * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * a_i * (

                        -PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[g0]*PQ[g1]*QC_1*QD_0*QD_1 - PQ[a0]*PQ[b0]*PQ[b1]*PQ[c1]*PQ[g0]*PQ[g1]*QC_0*QD_0*QD_1 - PQ[a0]*PQ[b0]*PQ[b1]*PQ[d0]*PQ[g0]*PQ[g1]*QC_0*QC_1*QD_1 - PQ[a0]*PQ[b0]*PQ[b1]*PQ[d1]*PQ[g0]*PQ[g1]*QC_0*QC_1*QD_0

                    )

                    + F9_t[6] * S1 * S1 * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * (

                        +PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*delta[d0][d1]*delta[g0][g1] + PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*delta[c1][d1]*delta[g0][g1] + PQ[a0]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d1]*delta[c1][d0]*delta[g0][g1] + PQ[a0]*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*delta[c0][d1]*delta[g0][g1] + PQ[a0]*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d1]*delta[c0][d0]*delta[g0][g1] + PQ[a0]*PQ[b0]*PQ[b1]*PQ[d0]*PQ[d1]*delta[c0][c1]*delta[g0][g1] + PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*PQ[d0]*delta[b1][d1]*delta[g0][g1] + PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*PQ[d1]*delta[b1][d0]*delta[g0][g1] + PQ[a0]*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]*delta[b1][c1]*delta[g0][g1] + PQ[a0]*PQ[b0]*PQ[c1]*PQ[d0]*PQ[d1]*delta[b1][c0]*delta[g0][g1] + PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*delta[b0][d1]*delta[g0][g1] + PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*delta[b0][d0]*delta[g0][g1] + PQ[a0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*delta[b0][c1]*delta[g0][g1] + PQ[a0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*delta[b0][c0]*delta[g0][g1] + PQ[a0]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*delta[b0][b1]*delta[g0][g1] + PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g0]*delta[a0][g1]*delta[d0][d1] + PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g1]*delta[a0][g0]*delta[d0][d1] + PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[g0]*delta[a0][g1]*delta[c1][d1] + PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[g1]*delta[a0][g0]*delta[c1][d1] + PQ[b0]*PQ[b1]*PQ[c0]*PQ[d1]*PQ[g0]*delta[a0][g1]*delta[c1][d0] + PQ[b0]*PQ[b1]*PQ[c0]*PQ[d1]*PQ[g1]*delta[a0][g0]*delta[c1][d0] + PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g0]*delta[a0][g1]*delta[c0][d1] + PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g1]*delta[a0][g0]*delta[c0][d1] + PQ[b0]*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g0]*delta[a0][g1]*delta[c0][d0] + PQ[b0]*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g1]*delta[a0][g0]*delta[c0][d0] + PQ[b0]*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g0]*delta[a0][g1]*delta[c0][c1] + PQ[b0]*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g1]*delta[a0][g0]*delta[c0][c1] + PQ[b0]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[g0]*delta[a0][g1]*delta[b1][d1] + PQ[b0]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[g1]*delta[a0][g0]*delta[b1][d1] + PQ[b0]*PQ[c0]*PQ[c1]*PQ[d1]*PQ[g0]*delta[a0][g1]*delta[b1][d0] + PQ[b0]*PQ[c0]*PQ[c1]*PQ[d1]*PQ[g1]*delta[a0][g0]*delta[b1][d0] + PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]*delta[a0][g1]*delta[b1][c1] + PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]*delta[a0][g0]*delta[b1][c1] + PQ[b0]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g0]*delta[a0][g1]*delta[b1][c0] + PQ[b0]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g1]*delta[a0][g0]*delta[b1][c0] + PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[g0]*delta[a0][g1]*delta[b0][d1] + PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[g1]*delta[a0][g0]*delta[b0][d1] + PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*PQ[g0]*delta[a0][g1]*delta[b0][d0] + PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*PQ[g1]*delta[a0][g0]*delta[b0][d0] + PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]*delta[a0][g1]*delta[b0][c1] + PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]*delta[a0][g0]*delta[b0][c1] + PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g0]*delta[a0][g1]*delta[b0][c0] + PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g1]*delta[a0][g0]*delta[b0][c0] + PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g0]*delta[a0][g1]*delta[b0][b1] + PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g1]*delta[a0][g0]*delta[b0][b1]

                        +PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*(delta[a0][d1]*delta[g0][g1] + delta[a0][g0]*delta[d1][g1] + delta[a0][g1]*delta[d1][g0]) + PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*(delta[a0][d0]*delta[g0][g1] + delta[a0][g0]*delta[d0][g1] + delta[a0][g1]*delta[d0][g0]) + PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*(delta[a0][c1]*delta[g0][g1] + delta[a0][g0]*delta[c1][g1] + delta[a0][g1]*delta[c1][g0]) + PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*(delta[a0][c0]*delta[g0][g1] + delta[a0][g0]*delta[c0][g1] + delta[a0][g1]*delta[c0][g0]) + PQ[b0]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0])

                    )


                );

        ERIs[threadIdx.y][threadIdx.x] += eri_ijkl * dd_mat_D[kl] * kl_factor;

    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < pd_prim_pair_count_local))
    {
        double hess_ii_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM; n++)
        {
            hess_ii_xy += ERIs[n][threadIdx.x];
        }

        atomicAdd(hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + i], hess_ii_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }
}

__global__ void __launch_bounds__(TILE_SIZE_J)
computeCoulombHessianPDDD_II_71(double*         hess_xy,
                               const uint32_t  hess_cart_ind_0,
                               const uint32_t  hess_cart_ind_1,
                               const double    prefac_coulomb,
                               const double*   p_prim_info,
                               const uint32_t  p_prim_count,
                               const double*   d_prim_info,
                               const uint32_t  d_prim_count,
                               const double*   pd_mat_D_local,
                               const double*   dd_mat_D,
                               const double*   pd_mat_Q_local,
                               const double*   dd_mat_Q,
                               const uint32_t* pd_first_inds_local,
                               const uint32_t* pd_second_inds_local,
                               const double*   pd_pair_data_local,
                               const uint32_t  pd_prim_pair_count_local,
                               const uint32_t* dd_first_inds,
                               const uint32_t* dd_second_inds,
                               const double*   dd_pair_data,
                               const uint32_t  dd_prim_pair_count,
                               const uint32_t* prim_cart_ao_to_atom_inds,
                               const uint32_t  s_prim_count,
                               const double*   boys_func_table,
                               const double*   boys_func_ft,
                               const double    eri_threshold)
{
    // each thread row scans over [ij|??] and sum up to a primitive J matrix element
    // J. Chem. Theory Comput. 2009, 5, 4, 1004-1015

    __shared__ double   ERIs[TILE_DIM][TILE_DIM + 1];
    __shared__ uint32_t d_cart_inds[6][2];
    __shared__ double   delta[3][3];
    __shared__ uint32_t g0, g1;

    const uint32_t ij = blockDim.x * blockIdx.x + threadIdx.x;

