*QC_0*QC_1) + delta[a0][d1]*delta[b1][g0]*(PB_0*PB_y*PQ[c0]*QC_1*QD_0 + PB_0*PB_y*PQ[c1]*QC_0*QD_0 + PB_0*PB_y*PQ[d0]*QC_0*QC_1) + delta[a0][d1]*delta[b1][g1]*(PB_0*PB_x*PQ[c0]*QC_1*QD_0 + PB_0*PB_x*PQ[c1]*QC_0*QD_0 + PB_0*PB_x*PQ[d0]*QC_0*QC_1) + delta[a0][d1]*delta[g0][g1]*(PB_0*PB_1*PQ[c0]*QC_1*QD_0 + PB_0*PB_1*PQ[c1]*QC_0*QD_0 + PB_0*PB_1*PQ[d0]*QC_0*QC_1)

                        +(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0])*(-PB_1*PQ[c0]*PQ[c1]*QD_0*QD_1 - PB_1*PQ[c0]*PQ[d0]*QC_1*QD_1 - PB_1*PQ[c0]*PQ[d1]*QC_1*QD_0 - PB_1*PQ[c1]*PQ[d0]*QC_0*QD_1 - PB_1*PQ[c1]*PQ[d1]*QC_0*QD_0 - PB_1*PQ[d0]*PQ[d1]*QC_0*QC_1) + (delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0])*(-PB_0*PQ[c0]*PQ[c1]*QD_0*QD_1 - PB_0*PQ[c0]*PQ[d0]*QC_1*QD_1 - PB_0*PQ[c0]*PQ[d1]*QC_1*QD_0 - PB_0*PQ[c1]*PQ[d0]*QC_0*QD_1 - PB_0*PQ[c1]*PQ[d1]*QC_0*QD_0 - PB_0*PQ[d0]*PQ[d1]*QC_0*QC_1)

