                    + F9_t[2] * (-0.5) * S1 * inv_S4 * inv_S4 * (

                        +(delta[b0][g0]*delta[b1][g1]*delta[c0][c1] + delta[b0][g1]*delta[b1][g0]*delta[c0][c1])*(PQ[a0]*PQ[d0]*QD_1 + PQ[a0]*PQ[d1]*QD_0 + PQ[a0]*QD_0*QD_1) + (delta[b0][g0]*delta[b1][g1]*delta[c0][d0] + delta[b0][g1]*delta[b1][g0]*delta[c0][d0])*(PQ[a0]*PQ[c1]*QD_1 + PQ[a0]*PQ[d1]*QC_1 + PQ[a0]*QC_1*QD_1) + (delta[b0][g0]*delta[b1][g1]*delta[c0][d1] + delta[b0][g1]*delta[b1][g0]*delta[c0][d1])*(PQ[a0]*PQ[c1]*QD_0 + PQ[a0]*PQ[d0]*QC_1 + PQ[a0]*QC_1*QD_0) + (delta[b0][g0]*delta[b1][g1]*delta[c1][d0] + delta[b0][g1]*delta[b1][g0]*delta[c1][d0])*(PQ[a0]*PQ[c0]*QD_1 + PQ[a0]*PQ[d1]*QC_0 + PQ[a0]*QC_0*QD_1) + (delta[b0][g0]*delta[b1][g1]*delta[c1][d1] + delta[b0][g1]*delta[b1][g0]*delta[c1][d1])*(PQ[a0]*PQ[c0]*QD_0 + PQ[a0]*PQ[d0]*QC_0 + PQ[a0]*QC_0*QD_0) + (delta[b0][g0]*delta[b1][g1]*delta[d0][d1] + delta[b0][g1]*delta[b1][g0]*delta[d0][d1])*(PQ[a0]*PQ[c0]*QC_1 + PQ[a0]*PQ[c1]*QC_0 + PQ[a0]*QC_0*QC_1)

                        +(delta[a0][c0]*delta[b0][g0]*delta[b1][g1] + delta[a0][c0]*delta[b0][g1]*delta[b1][g0])*(PQ[c1]*QD_0*QD_1 + PQ[d0]*QC_1*QD_1 + PQ[d1]*QC_1*QD_0) + (delta[a0][c1]*delta[b0][g0]*delta[b1][g1] + delta[a0][c1]*delta[b0][g1]*delta[b1][g0])*(PQ[c0]*QD_0*QD_1 + PQ[d0]*QC_0*QD_1 + PQ[d1]*QC_0*QD_0) + (delta[a0][d0]*delta[b0][g0]*delta[b1][g1] + delta[a0][d0]*delta[b0][g1]*delta[b1][g0])*(PQ[c0]*QC_1*QD_1 + PQ[c1]*QC_0*QD_1 + PQ[d1]*QC_0*QC_1) + (delta[a0][d1]*delta[b0][g0]*delta[b1][g1] + delta[a0][d1]*delta[b0][g1]*delta[b1][g0])*(PQ[c0]*QC_1*QD_0 + PQ[c1]*QC_0*QD_0 + PQ[d0]*QC_0*QC_1)

