        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[3] * 0.5 * inv_S4 * inv_S4 * inv_S4 * a_j * a_j * (

                        +(delta[a0][b0]*delta[c0][c1]*delta[d0][d1] + delta[a0][b0]*delta[c0][d0]*delta[c1][d1] + delta[a0][b0]*delta[c0][d1]*delta[c1][d0])*(2.0*PB_1*PB_x*PQ[g1] + 2.0*PB_1*PB_y*PQ[g0] - 2*PB_1*PQ[g0]*PQ[g1] + 2.0*PB_x*PB_y*PQ[b1] - 2*PB_x*PQ[b1]*PQ[g1] - 2*PB_y*PQ[b1]*PQ[g0]) + (delta[a0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][b1]*delta[c0][d1]*delta[c1][d0])*(2.0*PB_0*PB_x*PQ[g1] + 2.0*PB_0*PB_y*PQ[g0] - 2*PB_0*PQ[g0]*PQ[g1] + 2.0*PB_x*PB_y*PQ[b0] - 2*PB_x*PQ[b0]*PQ[g1] - 2*PB_y*PQ[b0]*PQ[g0]) + (delta[a0][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[c0][d1]*delta[c1][d0])*(2.0*PB_0*PB_1*PQ[g1] + 2.0*PB_0*PB_y*PQ[b1] - 2*PB_0*PQ[b1]*PQ[g1] + 2.0*PB_1*PB_y*PQ[b0] - 2*PB_1*PQ[b0]*PQ[g1] - 2*PB_y*PQ[b0]*PQ[b1]) + (delta[a0][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g1]*delta[c0][d1]*delta[c1][d0])*(2.0*PB_0*PB_1*PQ[g0] + 2.0*PB_0*PB_x*PQ[b1] - 2*PB_0*PQ[b1]*PQ[g0] + 2.0*PB_1*PB_x*PQ[b0] - 2*PB_1*PQ[b0]*PQ[g0] - 2*PB_x*PQ[b0]*PQ[b1]) + (delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[b0][b1]*delta[c0][d1]*delta[c1][d0])*(2.0*PA_0*PB_x*PQ[g1] + 2.0*PA_0*PB_y*PQ[g0] - 2*PA_0*PQ[g0]*PQ[g1] + 2.0*PB_x*PB_y*PQ[a0] - 2*PB_x*PQ[a0]*PQ[g1] - 2*PB_y*PQ[a0]*PQ[g0]) + (delta[b0][g0]*delta[c0][c1]*delta[d0][d1] + delta[b0][g0]*delta[c0][d0]*delta[c1][d1] + delta[b0][g0]*delta[c0][d1]*delta[c1][d0])*(2.0*PA_0*PB_1*PQ[g1] + 2.0*PA_0*PB_y*PQ[b1] - 2*PA_0*PQ[b1]*PQ[g1] + 2.0*PB_1*PB_y*PQ[a0] - 2*PB_1*PQ[a0]*PQ[g1] - 2*PB_y*PQ[a0]*PQ[b1]) + (delta[b0][g1]*delta[c0][c1]*delta[d0][d1] + delta[b0][g1]*delta[c0][d0]*delta[c1][d1] + delta[b0][g1]*delta[c0][d1]*delta[c1][d0])*(2.0*PA_0*PB_1*PQ[g0] + 2.0*PA_0*PB_x*PQ[b1] - 2*PA_0*PQ[b1]*PQ[g0] + 2.0*PB_1*PB_x*PQ[a0] - 2*PB_1*PQ[a0]*PQ[g0] - 2*PB_x*PQ[a0]*PQ[b1]) + (delta[b1][g0]*delta[c0][c1]*delta[d0][d1] + delta[b1][g0]*delta[c0][d0]*delta[c1][d1] + delta[b1][g0]*delta[c0][d1]*delta[c1][d0])*(2.0*PA_0*PB_0*PQ[g1] + 2.0*PA_0*PB_y*PQ[b0] - 2*PA_0*PQ[b0]*PQ[g1] + 2.0*PB_0*PB_y*PQ[a0] - 2*PB_0*PQ[a0]*PQ[g1] - 2*PB_y*PQ[a0]*PQ[b0]) + (delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[b1][g1]*delta[c0][d1]*delta[c1][d0])*(2.0*PA_0*PB_0*PQ[g0] + 2.0*PA_0*PB_x*PQ[b0] - 2*PA_0*PQ[b0]*PQ[g0] + 2.0*PB_0*PB_x*PQ[a0] - 2*PB_0*PQ[a0]*PQ[g0] - 2*PB_x*PQ[a0]*PQ[b0]) + (delta[c0][c1]*delta[d0][d1]*delta[g0][g1] + delta[c0][d0]*delta[c1][d1]*delta[g0][g1] + delta[c0][d1]*delta[c1][d0]*delta[g0][g1])*(2.0*PA_0*PB_0*PQ[b1] + 2.0*PA_0*PB_1*PQ[b0] - 2*PA_0*PQ[b0]*PQ[b1] + 2.0*PB_0*PB_1*PQ[a0] - 2*PB_0*PQ[a0]*PQ[b1] - 2*PB_1*PQ[a0]*PQ[b0])

