g1] + delta[b0][g1]*delta[c0][g0])*(PA_0*PB_1*PQ[c1]*PQ[d0]*QD_1 + PA_0*PB_1*PQ[c1]*PQ[d1]*QD_0 + PA_0*PB_1*PQ[d0]*PQ[d1]*QC_1) + (delta[b0][c1]*delta[g0][g1] + delta[b0][g0]*delta[c1][g1] + delta[b0][g1]*delta[c1][g0])*(PA_0*PB_1*PQ[c0]*PQ[d0]*QD_1 + PA_0*PB_1*PQ[c0]*PQ[d1]*QD_0 + PA_0*PB_1*PQ[d0]*PQ[d1]*QC_0) + (delta[b0][d0]*delta[g0][g1] + delta[b0][g0]*delta[d0][g1] + delta[b0][g1]*delta[d0][g0])*(PA_0*PB_1*PQ[c0]*PQ[c1]*QD_1 + PA_0*PB_1*PQ[c0]*PQ[d1]*QC_1 + PA_0*PB_1*PQ[c1]*PQ[d1]*QC_0) + (delta[b0][d1]*delta[g0][g1] + delta[b0][g0]*delta[d1][g1] + delta[b0][g1]*delta[d1][g0])*(PA_0*PB_1*PQ[c0]*PQ[c1]*QD_0 + PA_0*PB_1*PQ[c0]*PQ[d0]*QC_1 + PA_0*PB_1*PQ[c1]*PQ[d0]*QC_0) + (delta[b1][c0]*delta[g0][g1] + delta[b1][g0]*delta[c0][g1] + delta[b1][g1]*delta[c0][g0])*(PA_0*PB_0*PQ[c1]*PQ[d0]*QD_1 + PA_0*PB_0*PQ[c1]*PQ[d1]*QD_0 + PA_0*PB_0*PQ[d0]*PQ[d1]*QC_1) + (delta[b1][c1]*delta[g0][g1] + delta[b1][g0]*delta[c1][g1] + delta[b1][g1]*delta[c1][g0])*(PA_0*PB_0*PQ[c0]*PQ[d0]*QD_1 + PA_0*PB_0*PQ[c0]*PQ[d1]*QD_0 + PA_0*PB_0*PQ[d0]*PQ[d1]*QC_0) + (delta[b1][d0]*delta[g0][g1] + delta[b1][g0]*delta[d0][g1] + delta[b1][g1]*delta[d0][g0])*(PA_0*PB_0*PQ[c0]*PQ[c1]*QD_1 + PA_0*PB_0*PQ[c0]*PQ[d1]*QC_1 + PA_0*PB_0*PQ[c1]*PQ[d1]*QC_0) + (delta[b1][d1]*delta[g0][g1] + delta[b1][g0]*delta[d1][g1] + delta[b1][g1]*delta[d1][g0])*(PA_0*PB_0*PQ[c0]*PQ[c1]*QD_0 + PA_0*PB_0*PQ[c0]*PQ[d0]*QC_1 + PA_0*PB_0*PQ[c1]*PQ[d0]*QC_0)

