                        +(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])*(-PB_y*PQ[c0]*QC_1*QD_0*QD_1 - PB_y*PQ[c1]*QC_0*QD_0*QD_1 - PB_y*PQ[d0]*QC_0*QC_1*QD_1 - PB_y*PQ[d1]*QC_0*QC_1*QD_0 + 2.0*PQ[c0]*PQ[g1]*QC_1*QD_0*QD_1 + 2.0*PQ[c1]*PQ[g1]*QC_0*QD_0*QD_1 + 2.0*PQ[d0]*PQ[g1]*QC_0*QC_1*QD_1 + 2.0*PQ[d1]*PQ[g1]*QC_0*QC_1*QD_0) + (delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1])*(-PB_x*PQ[c0]*QC_1*QD_0*QD_1 - PB_x*PQ[c1]*QC_0*QD_0*QD_1 - PB_x*PQ[d0]*QC_0*QC_1*QD_1 - PB_x*PQ[d1]*QC_0*QC_1*QD_0 + 2.0*PQ[c0]*PQ[g0]*QC_1*QD_0*QD_1 + 2.0*PQ[c1]*PQ[g0]*QC_0*QD_0*QD_1 + 2.0*PQ[d0]*PQ[g0]*QC_0*QC_1*QD_1 + 2.0*PQ[d1]*PQ[g0]*QC_0*QC_1*QD_0) + (delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0])*(-PB_1*PQ[c0]*QC_1*QD_0*QD_1 - PB_1*PQ[c1]*QC_0*QD_0*QD_1 - PB_1*PQ[d0]*QC_0*QC_1*QD_1 - PB_1*PQ[d1]*QC_0*QC_1*QD_0 + 2.0*PQ[b1]*PQ[c0]*QC_1*QD_0*QD_1 + 2.0*PQ[b1]*PQ[c1]*QC_0*QD_0*QD_1 + 2.0*PQ[b1]*PQ[d0]*QC_0*QC_1*QD_1 + 2.0*PQ[b1]*PQ[d1]*QC_0*QC_1*QD_0) + (delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0])*(-PB_0*PQ[c0]*QC_1*QD_0*QD_1 - PB_0*PQ[c1]*QC_0*QD_0*QD_1 - PB_0*PQ[d0]*QC_0*QC_1*QD_1 - PB_0*PQ[d1]*QC_0*QC_1*QD_0 + 2.0*PQ[b0]*PQ[c0]*QC_1*QD_0*QD_1 + 2.0*PQ[b0]*PQ[c1]*QC_0*QD_0*QD_1 + 2.0*PQ[b0]*PQ[d0]*QC_0*QC_1*QD_1 + 2.0*PQ[b0]*PQ[d1]*QC_0*QC_1*QD_0) + (delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])*(-PA_0*PQ[c0]*QC_1*QD_0*QD_1 - PA_0*PQ[c1]*QC_0*QD_0*QD_1 - PA_0*PQ[d0]*QC_0*QC_1*QD_1 - PA_0*PQ[d1]*QC_0*QC_1*QD_0 + 2.0*PQ[a0]*PQ[c0]*QC_1*QD_0*QD_1 + 2.0*PQ[a0]*PQ[c1]*QC_0*QD_0*QD_1 + 2.0*PQ[a0]*PQ[d0]*QC_0*QC_1*QD_1 + 2.0*PQ[a0]*PQ[d1]*QC_0*QC_1*QD_0)

