0][c0]*delta[b0][d0]*delta[b1][g0] + delta[a0][c0]*delta[b0][g0]*delta[b1][d0] + delta[a0][d0]*delta[b0][c0]*delta[b1][g0] + delta[a0][d0]*delta[b0][g0]*delta[b1][c0]) - PQ[g1]*QD_0*QD_1*(delta[a0][c0]*delta[b0][c1]*delta[b1][g0] + delta[a0][c0]*delta[b0][g0]*delta[b1][c1] + delta[a0][c1]*delta[b0][c0]*delta[b1][g0] + delta[a0][c1]*delta[b0][g0]*delta[b1][c0])

