        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[3] * 0.25 * S1 * S1 * inv_S2 * inv_S4 * inv_S4 * inv_S4 * (

                        +PQ[a0]*(delta[b0][g0]*delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[b0][g0]*delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[b0][g0]*delta[b1][g1]*delta[c0][d1]*delta[c1][d0] + delta[b0][g1]*delta[b1][g0]*delta[c0][c1]*delta[d0][d1] + delta[b0][g1]*delta[b1][g0]*delta[c0][d0]*delta[c1][d1] + delta[b0][g1]*delta[b1][g0]*delta[c0][d1]*delta[c1][d0]) + PQ[c0]*(delta[a0][c1]*delta[b0][g0]*delta[b1][g1]*delta[d0][d1] + delta[a0][c1]*delta[b0][g1]*delta[b1][g0]*delta[d0][d1] + delta[a0][d0]*delta[b0][g0]*delta[b1][g1]*delta[c1][d1] + delta[a0][d0]*delta[b0][g1]*delta[b1][g0]*delta[c1][d1] + delta[a0][d1]*delta[b0][g0]*delta[b1][g1]*delta[c1][d0] + delta[a0][d1]*delta[b0][g1]*delta[b1][g0]*delta[c1][d0]) + PQ[c1]*(delta[a0][c0]*delta[b0][g0]*delta[b1][g1]*delta[d0][d1] + delta[a0][c0]*delta[b0][g1]*delta[b1][g0]*delta[d0][d1] + delta[a0][d0]*delta[b0][g0]*delta[b1][g1]*delta[c0][d1] + delta[a0][d0]*delta[b0][g1]*delta[b1][g0]*delta[c0][d1] + delta[a0][d1]*delta[b0][g0]*delta[b1][g1]*delta[c0][d0] + delta[a0][d1]*delta[b0][g1]*delta[b1][g0]*delta[c0][d0]) + PQ[d0]*(delta[a0][c0]*delta[b0][g0]*delta[b1][g1]*delta[c1][d1] + delta[a0][c0]*delta[b0][g1]*delta[b1][g0]*delta[c1][d1] + delta[a0][c1]*delta[b0][g0]*delta[b1][g1]*delta[c0][d1] + delta[a0][c1]*delta[b0][g1]*delta[b1][g0]*delta[c0][d1] + delta[a0][d1]*delta[b0][g0]*delta[b1][g1]*delta[c0][c1] + delta[a0][d1]*delta[b0][g1]*delta[b1][g0]*delta[c0][c1]) + PQ[d1]*(delta[a0][c0]*delta[b0][g0]*delta[b1][g1]*delta[c1][d0] + delta[a0][c0]*delta[b0][g1]*delta[b1][g0]*delta[c1][d0] + delta[a0][c1]*delta[b0][g0]*delta[b1][g1]*delta[c0][d0] + delta[a0][c1]*delta[b0][g1]*delta[b1][g0]*delta[c0][d0] + delta[a0][d0]*delta[b0][g0]*delta[b1][g1]*delta[c0][c1] + delta[a0][d0]*delta[b0][g1]*delta[b1][g0]*delta[c0][c1])

                    )

