                        +(-2*PQ[c0]*PQ[c1]*QD_0 - 2*PQ[c0]*PQ[d0]*QC_1 - 2*PQ[c1]*PQ[d0]*QC_0)*(delta[a0][b0]*delta[b1][d1]*delta[g0][g1] + delta[a0][b0]*delta[b1][g0]*delta[d1][g1] + delta[a0][b0]*delta[b1][g1]*delta[d1][g0] + delta[a0][b1]*delta[b0][d1]*delta[g0][g1] + delta[a0][b1]*delta[b0][g0]*delta[d1][g1] + delta[a0][b1]*delta[b0][g1]*delta[d1][g0] + delta[a0][d1]*delta[b0][b1]*delta[g0][g1] + delta[a0][d1]*delta[b0][g0]*delta[b1][g1] + delta[a0][d1]*delta[b0][g1]*delta[b1][g0] + delta[a0][g0]*delta[b0][b1]*delta[d1][g1] + delta[a0][g0]*delta[b0][d1]*delta[b1][g1] + delta[a0][g0]*delta[b0][g1]*delta[b1][d1] + delta[a0][g1]*delta[b0][b1]*delta[d1][g0] + delta[a0][g1]*delta[b0][d1]*delta[b1][g0] + delta[a0][g1]*delta[b0][g0]*delta[b1][d1]) + (-2*PQ[c0]*PQ[c1]*QD_1 - 2*PQ[c0]*PQ[d1]*QC_1 - 2*PQ[c1]*PQ[d1]*QC_0)*(delta[a0][b0]*delta[b1][d0]*delta[g0][g1] + delta[a0][b0]*delta[b1][g0]*delta[d0][g1] + delta[a0][b0]*delta[b1][g1]*delta[d0][g0] + delta[a0][b1]*delta[b0][d0]*delta[g0][g1] + delta[a0][b1]*delta[b0][g0]*delta[d0][g1] + delta[a0][b1]*delta[b0][g1]*delta[d0][g0] + delta[a0][d0]*delta[b0][b1]*delta[g0][g1] + delta[a0][d0]*delta[b0][g0]*delta[b1][g1] + delta[a0][d0]*delta[b0][g1]*delta[b1][g0] + delta[a0][g0]*delta[b0][b1]*delta[d0][g1] + delta[a0][g0]*delta[b0][d0]*delta[b1][g1] + delta[a0][g0]*delta[b0][g1]*delta[b1][d0] + delta[a0][g1]*delta[b0][b1]*delta[d0][g0] + delta[a0][g1]*delta[b0][d0]*delta[b1][g0] + delta[a0][g1]*delta[b0][g0]*delta[b1][d0]) + (-2*PQ[c0]*PQ[d0]*QD_1 - 2*PQ[c0]*PQ[d1]*QD_0 - 2*PQ[d0]*PQ[d1]*QC_0)*(delta[a0][b0]*delta[b1][c1]*delta[g0][g1] + delta[a0][b0]*delta[b1][g0]*delta[c1][g1] + delta[a0][b0]*delta[b1][g1]*delta[c1][g0] + delta[a0][b1]*delta[b0][c1]*delta[g0][g1] + delta[a0][b1]*delta[b0][g0]*delta[c1][g1] + delta[a0][b1]*delta[b0][g1]*delta[c1][g0] + delta[a0][c1]*delta[b0][b1]*delta[g0][g1] + delta[a0][c1]*delta[b0][g0]*delta[b1][g1] + delta[a0][c1]*delta[b0][g1]*delta[b1][g0] + delta[a0][g0]*delta[b0][b1]*delta[c1][g1] + 