1] + PA_x*PB_0*PB_1*QC_0*QC_1*delta[a0][g1]*delta[d0][d1] + PA_x*PB_0*PB_1*QC_0*QD_0*delta[a0][g1]*delta[c1][d1] + PA_x*PB_0*PB_1*QC_0*QD_1*delta[a0][g1]*delta[c1][d0] + PA_x*PB_0*PB_1*QC_1*QD_0*delta[a0][g1]*delta[c0][d1] + PA_x*PB_0*PB_1*QC_1*QD_1*delta[a0][g1]*delta[c0][d0] + PA_x*PB_0*PB_1*QD_0*QD_1*delta[a0][g1]*delta[c0][c1] + PA_x*PB_0*PB_y*QC_0*QC_1*delta[a0][b1]*delta[d0][d1] + PA_x*PB_0*PB_y*QC_0*QD_0*delta[a0][b1]*delta[c1][d1] + PA_x*PB_0*PB_y*QC_0*QD_1*delta[a0][b1]*delta[c1][d0] + PA_x*PB_0*PB_y*QC_1*QD_0*delta[a0][b1]*delta[c0][d1] + PA_x*PB_0*PB_y*QC_1*QD_1*delta[a0][b1]*delta[c0][d0] + PA_x*PB_0*PB_y*QD_0*QD_1*delta[a0][b1]*delta[c0][c1] + PA_x*PB_1*PB_y*QC_0*QC_1*delta[a0][b0]*delta[d0][d1] + PA_x*PB_1*PB_y*QC_0*QD_0*delta[a0][b0]*delta[c1][d1] + PA_x*PB_1*PB_y*QC_0*QD_1*delta[a0][b0]*delta[c1][d0] + PA_x*PB_1*PB_y*QC_1*QD_0*delta[a0][b0]*delta[c0][d1] + PA_x*PB_1*PB_y*QC_1*QD_1*delta[a0][b0]*delta[c0][d0] + PA_x*PB_1*PB_y*QD_0*QD_1*delta[a0][b0]*delta[c0][c1] + PB_0*PB_1*PB_y*QC_0*QC_1*delta[a0][g0]*delta[d0][d1] + PB_0*PB_1*PB_y*QC_0*QD_0*delta[a0][g0]*delta[c1][d1] + PB_0*PB_1*PB_y*QC_0*QD_1*delta[a0][g0]*delta[c1][d0] + PB_0*PB_1*PB_y*QC_1*QD_0*delta[a0][g0]*delta[c0][d1] + PB_0*PB_1*PB_y*QC_1*QD_1*delta[a0][g0]*delta[c0][d0] + PB_0*PB_1*PB_y*QD_0*QD_1*delta[a0][g0]*delta[c0][c1]

                    )

                    + F9_t[0] * (-0.5) * inv_S1 * inv_S2 * a_i * (

                        +PA_0*QC_0*QC_1*(delta[b0][g0]*delta[b1][g1]*delta[d0][d1] + delta[b0][g1]*delta[b1][g0]*delta[d0][d1]) + PA_0*QC_0*QD_0*(delta[b0][g0]*delta[b1][g1]*delta[c1][d1] + delta[b0][g1]*delta[b1][g0]*delta[c1][d1]) + PA_0*QC_0*QD_1*(delta[b0][g0]*delta[b1][g1]*delta[c1][d0] + delta[b0][g1]*delta[b1][g0]*delta[c1][d0]) + PA_0*QC_1*QD_0*(delta[b0][g0]*delta[b1][g1]*delta[c0][d1] + delta[b0][g1]*delta[b1][g0]*delta[c0][d1]) + PA_0*QC_1*QD_1*(delta[b0][g0]*delta[b1][g1]*delta[c0][d0] + delta[b0][g1]*delta[b1][g0]*delta[c0][d0]) + PA_0*QD_0*QD_1*(delta[b0][g0]*delta[b1][g1]*delta[c0][c1] + delta[b0][g1]*delta[b1][g0]*delta[c0][c1]) + PA_x*QC_0*QC_1*(delta[a0][b0]*delta[b1][g1]*delta[d0][d1] + delta[a0][b1]*delta[b0][g1]*delta[d0][d1]) + PA_x*QC_0*QD_0*(delta[a0][b0]*delta[b1][g1]*delta[c1][d1] + delta[a0][b1]*delta[b0][g1]*delta[c1][d1]) + PA_x*QC_0*QD_1*(delta[a0][b0]*delta[b1][g1]*delta[c1][d0] + delta[a0][b1]*delta[b0][g1]*delta[c1][d0]) + PA_x*QC_1*QD_0*(delta[a0][b0]*delta[b1][g1]*delta[c0][d1] + delta[a0][b1]*delta[b0][g1]*delta[c0][d1]) + PA_x*QC_1*QD_1*(delta[a0][b0]*delta[b1][g1]*delta[c0][d0] + delta[a0][b1]*delta[b0][g1]*delta[c0][d0]) + PA_x*QD_0*QD_1*(delta[a0][b0]*delta[b1][g1]*delta[c0][c1] + delta[a0][b1]*delta[b0][g1]*delta[c0][c1])

                        +PB_0*QC_0*QC_1*delta[a0][g0]*delta[b1][g1]*delta[d0][d1] + PB_0*QC_0*QD_0*delta[a0][g0]*delta[b1][g1]*delta[c1][d1] + PB_0*QC_0*QD_1*delta[a0][g0]*delta[b1][g1]*delta[c1][d0] + PB_0*QC_1*QD_0*delta[a0][g0]*delta[b1][g1]*delta[c0][d1] + PB_0*QC_1*QD_1*delta[a0][g0]*delta[b1][g1]*delta[c0][d0] + PB_0*QD_0*QD_1*delta[a0][g0]*delta[b1][g1]*delta[c0][c1] + PB_1*QC_0*QC_1*delta[a0][g0]*delta[b0][g1]*delta[d0][d1] + PB_1*QC_0*QD_0*delta[a0][g0]*delta[b0][g1]*delta[c1][d1] + PB_1*QC_0*QD_1*delta[a0][g0]*delta[b0][g1]*delta[c1][d0] + PB_1*QC_1*QD_0*delta[a0][g0]*delta[b0][g1]*delta[c0][d1] + PB_1*QC_1*QD_1*delta[a0][g0]*delta[b0][g1]*delta[c0][d0] + PB_1*QD_0*QD_1*delta[a0][g0]*delta[b0][g1]*delta[c0][c1]

                    )

                    + F9_t[0] * (-0.5) * inv_S1 * inv_S2 * a_j * (

                        +PB_0*QC_0*QC_1*delta[a0][g0]*delta[b1][g1]*delta[d0][d1] + PB_0*QC_0*QD_0*delta[a0][g0]*delta[b1][g1]*delta[c1][d1] + PB_0*QC_0*QD_1*delta[a0][g0]*delta[b1][g1]*delta[c1][d0] + PB_0*QC_1*QD_0*delta[a0][g0]*delta[b1][g1]*delta[c0][d1] + PB_0*QC_1*QD_1*delta[a0][g0]*delta[b1][g1]*delta[c0][d0] + PB_0*QD_0*QD_1*delta[a0][g0]*delta[b1][g1]*delta[c0][c1] + PB_1*QC_0*QC_1*delta[a0][g0]*delta[b0][g1]*delta[d0][d1] + PB_1*QC_0*QD_0*delta[a0][g0]*delta[b0][g1]*delta[c1][d1] + PB_1*QC_0*QD_1*delta[a0][g0]*delta[b0][g1]*delta[c1][d0] + PB_1*QC_1*QD_0*delta[a0][g0]*delta[b0][g1]*delta[c0][d1] + PB_1*QC_1*QD_1*delta[a0][g0]*delta[b0][g1]*delta[c0][d0] + PB_1*QD_0*QD_1*delta[a0][g0]*delta[b0][g1]*delta[c0][c1] + PB_y*QC_0*QC_1*delta[a0][g0]*delta[b0][b1]*delta[d0][d1] + PB_y*QC_0*QD_0*delta[a0][g0]*delta[b0][b1]*delta[c1][d1] + PB_y*QC_0*QD_1*delta[a0][g0]*delta[b0][b1]*delta[c1][d0] + PB_y*QC_1*QD_0*delta[a0][g0]*delta[b0][b1]*delta[c0][d1] + PB_y*QC_1*QD_1*delta[a0][g0]*delta[b0][b1]*delta[c0][d0] + PB_y*QD_0*QD_1*delta[a0][g0]*delta[b0][b1]*delta[c0][c1]

                    )

                    + F9_t[0] * inv_S2 * inv_S2 * a_i * a_j * (

                        +PA_0*PA_x*PB_0*PB_1*PB_y*(delta[c0][c1]*delta[d0][d1] + delta[c0][d0]*delta[c1][d1] + delta[c0][d1]*delta[c1][d0])

                    )

                    + F9_t[0] * (-0.5) * inv_S2 * inv_S2 * a_i * (

                        +PA_0*PA_x*PB_0*(delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[b1][g1]*delta[c0][d1]*delta[c1][d0]) + PA_0*PA_x*PB_1*(delta[b0][g1]*delta[c0][c1]*delta[d0][d1] + delta[b0][g1]*delta[c0][d0]*delta[c1][d1] + delta[b0][g1]*delta[c0][d1]*delta[c1][d0])

                    )

                    + F9_t[0] * (-0.5) * inv_S2 * inv_S2 * a_j * (

                        +PB_0*PB_1*PB_y*(delta[a0][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[c0][d1]*delta[c1][d0])

                    )

                    + F9_t[0] * 0.25 * inv_S2 * inv_S2 * (

                        +PB_0*(delta[a0][g0]*delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b1][g1]*delta[c0][d1]*delta[c1][d0]) + PB_1*(delta[a0][g0]*delta[b0][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b0][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b0][g1]*delta[c0][d1]*delta[c1][d0])

                    )

                    + F9_t[0] * 2.0 * inv_S1 * a_i * a_j * (

                        +PA_0*PA_x*PB_0*QC_0*QC_1*QD_0*QD_1*delta[b1][g1] + PA_0*PA_x*PB_1*QC_0*QC_1*QD_0*QD_1*delta[b0][g1] + PA_0*PA_x*PB_y*QC_0*QC_1*QD_0*QD_1*delta[b0][b1] + PA_0*PB_0*PB_1*QC_0*QC_1*QD_0*QD_1*delta[g0][g1] + PA_0*PB_0*PB_y*QC_0*QC_1*QD_0*QD_1*delta[b1][g0] + PA_0*PB_1*PB_y*QC_0*QC_1*QD_0*QD_1*delta[b0][g0] + PA_x*PB_0*PB_1*QC_0*QC_1*QD_0*QD_1*delta[a0][g1] + PA_x*PB_0*PB_y*QC_0*QC_1*QD_0*QD_1*delta[a0][b1] + PA_x*PB_1*PB_y*QC_0*QC_1*QD_0*QD_1*delta[a0][b0] + PB_0*PB_1*PB_y*QC_0*QC_1*QD_0*QD_1*delta[a0][g0]

                    )

                    + F9_t[0] * (-1.0) * inv_S1 * a_i * (

                        +PA_0*QC_0*QC_1*QD_0*QD_1*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*QC_0*QC_1*QD_0*QD_1*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1])

                        +PB_0*QC_0*QC_1*QD_0*QD_1*delta[a0][g0]*delta[b1][g1] + PB_1*QC_0*QC_1*QD_0*QD_1*delta[a0][g0]*delta[b0][g1]

                    )

                    + F9_t[0] * (-1.0) * inv_S1 * a_j * (

                        +PB_0*QC_0*QC_1*QD_0*QD_1*delta[a0][g0]*delta[b1][g1] + PB_1*QC_0*QC_1*QD_0*QD_1*delta[a0][g0]*delta[b0][g1] + PB_y*QC_0*QC_1*QD_0*QD_1*delta[a0][g0]*delta[b0][b1]

                    )

                    + F9_t[0] * 2.0 * inv_S2 * a_i * a_j * (

                        +PA_0*PA_x*PB_0*PB_1*PB_y*QC_0*QC_1*delta[d0][d1] + PA_0*PA_x*PB_0*PB_1*PB_y*QC_0*QD_0*delta[c1][d1] + PA_0*PA_x*PB_0*PB_1*PB_y*QC_0*QD_1*delta[c1][d0] + PA_0*PA_x*PB_0*PB_1*PB_y*QC_1*QD_0*delta[c0][d1] + PA_0*PA_x*PB_0*PB_1*PB_y*QC_1*QD_1*delta[c0][d0] + PA_0*PA_x*PB_0*PB_1*PB_y*QD_0*QD_1*delta[c0][c1]

                    )


                );

        ERIs[threadIdx.y][threadIdx.x] += eri_ijkl * dd_mat_D[kl] * kl_factor;

    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < pd_prim_pair_count_local))
    {
        double hess_ij_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM; n++)
        {
            hess_ij_xy += ERIs[n][threadIdx.x];
        }

        atomicAdd(
            hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + i] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + j],
            hess_ij_xy * ij_factor_D * 2.0 * prefac_coulomb);

        atomicAdd(
            hess_yx + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + j] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + i],
            hess_ij_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }
}

__global__ void __launch_bounds__(TILE_SIZE_J)
computeCoulombHessianPDDD_IJ_1(double*         hess_xy,
                               double*         hess_yx,
                               const uint32_t  hess_cart_ind_0,
                               const uint32_t  hess_cart_ind_1,
                               const double    prefac_coulomb,
                               const double*   p_prim_info,
                               const uint32_t  p_prim_count,
                               const double*   d_prim_info,
                               const uint32_t  d_prim_count,
                               const double*   pd_mat_D_local,
                               const double*   dd_mat_D,
                               const double*   pd_mat_Q_local,
                               const double*   dd_mat_Q,
                               const uint32_t* pd_first_inds_local,
                               const uint32_t* pd_second_inds_local,
                               const double*   pd_pair_data_local,
                               const uint32_t  pd_prim_pair_count_local,
                               const uint32_t* dd_first_inds,
                               const uint32_t* dd_second_inds,
                               const double*   dd_pair_data,
                               const uint32_t  dd_prim_pair_count,
                               const uint32_t* prim_cart_ao_to_atom_inds,
                               const uint32_t  natoms,
                               const uint32_t  s_prim_count,
                               const double*   boys_func_table,
                               const double*   boys_func_ft,
                               const double    eri_threshold)
{
    // each thread row scans over [ij|??] and sum up to a primitive J matrix element
    // J. Chem. Theory Comput. 2009, 5, 4, 1004-1015

    __shared__ double   ERIs[TILE_DIM][TILE_DIM + 1];
    __shared__ uint32_t d_cart_inds[6][2];
    __shared__ double   delta[3][3];
    __shared__ uint32_t g0, g1;

    const uint32_t ij = blockDim.x * blockIdx.x + threadIdx.x;

    double a_i, a_j, r_i[3], r_j[3], S_ij_00, S1, inv_S1, ij_factor_D;
    double PA_0, PB_0, PB_1, PA_x, PB_y;
    uint32_t i, j, a0, b0, b1;

    ERIs[threadIdx.y][threadIdx.x] = 0.0;

    if ((threadIdx.y == 0) && (threadIdx.x == 0))
    {
        d_cart_inds[0][0] = 0; d_cart_inds[0][1] = 0;
        d_cart_inds[1][0] = 0; d_cart_inds[1][1] = 1;
        d_cart_inds[2][0] = 0; d_cart_inds[2][1] = 2;
        d_cart_inds[3][0] = 1; d_cart_inds[3][1] = 1;
        d_cart_inds[4][0] = 1; d_cart_inds[4][1] = 2;
        d_cart_inds[5][0] = 2; d_cart_inds[5][1] = 2;

        delta[0][0] = 1.0; delta[0][1] = 0.0; delta[0][2] = 0.0;
        delta[1][0] = 0.0; delta[1][1] = 1.0; delta[1][2] = 0.0;
