        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[1] * S1 * inv_S2 * inv_S2 * inv_S4 * a_i * (

                        +PA_0*PA_x*PB_0*(delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[b1][g1]*delta[c0][d1]*delta[c1][d0]) + PA_0*PA_x*PB_1*(delta[b0][g1]*delta[c0][c1]*delta[d0][d1] + delta[b0][g1]*delta[c0][d0]*delta[c1][d1] + delta[b0][g1]*delta[c0][d1]*delta[c1][d0])

                    )

                    + F9_t[1] * S1 * inv_S2 * inv_S2 * inv_S4 * a_j * (

                        +PB_0*PB_1*PB_y*(delta[a0][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[c0][d1]*delta[c1][d0])

