                        +(-2*PA_0*QC_0*QC_1*QD_0*QD_1 + PQ[a0]*QC_0*QC_1*QD_0*QD_1)*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + (-2*PA_x*QC_0*QC_1*QD_0*QD_1 + PQ[g0]*QC_0*QC_1*QD_0*QD_1)*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1]) + (-2*PB_0*QC_0*QC_1*QD_0*QD_1 + PQ[b0]*QC_0*QC_1*QD_0*QD_1)*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + (-2*PB_1*QC_0*QC_1*QD_0*QD_1 + PQ[b1]*QC_0*QC_1*QD_0*QD_1)*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0]) + (-2*PB_y*QC_0*QC_1*QD_0*QD_1 + PQ[g1]*QC_0*QC_1*QD_0*QD_1)*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])

                    )

                    + F9_t[1] * inv_S1 * inv_S4 * a_i * a_j * (

                        +delta[a0][b0]*delta[c0][c1]*(-PA_x*PB_1*PB_y*QD_0*QD_1 + PA_x*PB_1*PQ[g1]*QD_0*QD_1 + PA_x*PB_y*PQ[b1]*QD_0*QD_1 + PB_1*PB_y*PQ[g0]*QD_0*QD_1) + delta[a0][b0]*delta[c0][d0]*(-PA_x*PB_1*PB_y*QC_1*QD_1 + PA_x*PB_1*PQ[g1]*QC_1*QD_1 + PA_x*PB_y*PQ[b1]*QC_1*QD_1 + PB_1*PB_y*PQ[g0]*QC_1*QD_1) + delta[a0][b0]*delta[c0][d1]*(-PA_x*PB_1*PB_y*QC_1*QD_0 + PA_x*PB_1*PQ[g1]*QC_1*QD_0 + PA_x*PB_y*PQ[b1]*QC_1*QD_0 + PB_1*PB_y*PQ[g0]*QC_1*QD_0) + delta[a0][b0]*delta[c1][d0]*(-PA_x*PB_1*PB_y*QC_0*QD_1 + PA_x*PB_1*PQ[g1]*QC_0*QD_1 + PA_x*PB_y*PQ[b1]*QC_0*QD_1 + PB_1*PB_y*PQ[g0]*QC_0*QD_1) + delta[a0][b0]*delta[c1][d1]*(-PA_x*PB_1*PB_y*QC_0*QD_0 + PA_x*PB_1*PQ[g1]*QC_0*QD_0 + PA_x*PB_y*PQ[b1]*QC_0*QD_0 + PB_1*PB_y*PQ[g0]*QC_0*QD_0) + delta[a0][b0]*delta[d0][d1]*(-PA_x*PB_1*PB_y*QC_0*QC_1 + PA_x*PB_1*PQ[g1]*QC_0*QC_1 + PA_x*PB_y*PQ[b1]*QC_0*QC_1 + PB_1*PB_y*PQ[g0]*QC_0*QC_1) + delta[a0][b1]*delta[c0][c1]*(-PA_x*PB_0*PB_y*QD_0*QD_1 + PA_x*PB_0*PQ[g1]*QD_0*QD_1 + PA_x*PB_y*PQ[b0]*QD_0*QD_1 + PB_0*PB_y*PQ[g0]*QD_0*QD_1) + delta[a0][b1]*delta[c0][d0]*(-PA_x*PB_0*PB_y*QC_1*QD_1 + PA_x*PB_0*PQ[g1]*QC_1*QD_1 + PA_x*PB_y*PQ[b0]*QC_1*QD_1 + PB_0*PB_y*PQ[g0]*QC_1*QD_1) + delta[a0][b1]*delta[c0][d1]*(-PA_x*PB_0*PB_y*QC_1*QD_0 + PA_x*PB_0*PQ[g1]*QC_1*QD_0 + PA_x*PB_y*PQ[b0]*QC_1*QD_0 + PB_0*PB_y*PQ[g0]*QC_1*QD_0) + delta[a0][b1]*delta[c1][d0]*(-PA_x*PB_0*PB_y*QC_0*QD_1 + PA_x*PB_0*PQ[g1]*QC_0*QD_1 + PA_x*PB_y*PQ[b0]*QC_0*QD_1 + PB_0*PB_y*PQ[g0]*QC_0*QD_1) + delta[a0][b1]*delta[c1][d1]*(-PA_x*PB_0*PB_y*QC_0*QD_0 + PA_x*PB_0*PQ[g1]*QC_0*QD_0 + PA_x*PB_y*PQ[b0]*QC_0*QD_0 + PB_0*PB_y*PQ[g0]*QC_0*QD_0) + delta[a0][b1]*delta[d0][d1]*(-PA_x*PB_0*PB_y*QC_0*QC_1 + PA_x*PB_0*PQ[g1]*QC_0*QC_1 + PA_x*PB_y*PQ[b0]*QC_0*QC_1 + PB_0*PB_y*PQ[g0]*QC_0*QC_1) + delta[a0][g0]*delta[c0][c1]*(-PB_0*PB_1*PB_y*QD_0*QD_1 + PB_0*PB_1*PQ[g1]*QD_0*QD_1 + PB_0*PB_y*PQ[b1]*QD_0*QD_1 + PB_1*PB_y*PQ[b0]*QD_0*QD_1) + delta[a0][g0]*delta[c0][d0]*(-PB_0*PB_1*PB_y*QC_1*QD_1 + PB_0*PB_1*PQ[g1]*QC_1*QD_1 + PB_0