                        +(-2*PA_0 + 4.0*PQ[a0])*(delta[b0][b1]*delta[c0][c1]*delta[d0][d1]*delta[g0][g1] + delta[b0][b1]*delta[c0][d0]*delta[c1][d1]*delta[g0][g1] + delta[b0][b1]*delta[c0][d1]*delta[c1][d0]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[b0][g0]*delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[b0][g0]*delta[b1][g1]*delta[c0][d1]*delta[c1][d0] + delta[b0][g1]*delta[b1][g0]*delta[c0][c1]*delta[d0][d1] + delta[b0][g1]*delta[b1][g0]*delta[c0][d0]*delta[c1][d1] + delta[b0][g1]*delta[b1][g0]*delta[c0][d1]*delta[c1][d0]) + (-2*PA_x + 4.0*PQ[g0])*(delta[a0][b0]*delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][b0]*delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][b0]*delta[b1][g1]*delta[c0][d1]*delta[c1][d0] + delta[a0][b1]*delta[b0][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][b1]*delta[b0][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][b1]*delta[b0][g1]*delta[c0][d1]*delta[c1][d0] + delta[a0][g1]*delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g1]*delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g1]*delta[b0][b1]*delta[c0][d1]*delta[c1][d0]) + (-2*PB_0 + 4.0*PQ[b0])*(delta[a0][b1]*delta[c0][c1]*delta[d0][d1]*delta[g0][g1] + delta[a0][b1]*delta[c0][d0]*delta[c1][d1]*delta[g0][g1] + delta[a0][b1]*delta[c0][d1]*delta[c1][d0]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b1][g1]*delta[c0][d1]*delta[c1][d0] + delta[a0][g1]*delta[b1][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][g1]*delta[b1][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][g1]*delta[b1][g0]*delta[c0][d1]*delta[c1][d0]) + (-2*PB_1 + 4.0*PQ[b1])*(delta[a0][b0]*delta[c0][c1]*delta[d0][d1]*delta[g0][g1] + delta[a0][b0]*delta[c0][d0]*delta[c1][d1]*delta[g0][g1] + delta[a0][b0]*delta[c0][d1]*delta[c1][d0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b0][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b0][g1]*delta[c0][d1]*delta[c1][d0] + delta[a0][g1]*delta[b0][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][g1]*delta[b0][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][g1]*delta[b0][g0]*delta[c0][d1]*delta[c1][d0]) + (-2*PB_y + 4.0*PQ[g1])*(delta[a0][b0]*delta[b1][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][b0]*delta[b1][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][b0]*delta[b1][g0]*delta[c0][d1]*delta[c1][d0] + delta[a0][b1]*delta[b0][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][b1]*delta[b0][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][b1]*delta[b0][g0]*delta[c0][d1]*delta[c1][d0] + delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[c1][d0])

                        +(-PA_0 + PQ[a0])*(delta[b0][b1]*delta[c0][c1]*delta[d0][g0]*delta[d1][g1] + delta[b0][b1]*delta[c0][c1]*delta[d0][g1]*delta[d1][g0] + delta[b0][b1]*delta[c0][d0]*delta[c1][g0]*delta[d1][g1] + delta[b0][b1]*delta[c0][d0]*delta[c1][g1]*delta[d1][g0] + delta[b0][b1]*delta[c0][d1]*delta[c1][g0]*delta[d0][g1] + delta[b0][b1]*delta[c0][d1]*delta[c1][g1]*delta[d0][g0] + delta[b0][b1]*delta[c0][g0]*delta[c1][d0]*delta[d1][g1] + delta[b0][b1]*delta[c0][g0]*delta[c1][d1]*delta[d0][g1] + delta[b0][b1]*delta[c0][g0]*delta[c1][g1]*delta[d0][d1] + delta[b0][b1]*delta[c0][g1]*delta[c1][d0]*delta[d1][g0] + delta[b0][b1]*delta[c0][g1]*delta[c1][d1]*delta[d0][g0] + delta[b0][b1]*delta[c0][g1]*delta[c1][g0]*delta[d0][d1] + delta[b0][c0]*delta[b1][c1]*delta[d0][d1]*delta[g0][g1] + delta[b0][c0]*delta[b1][d0]*delta[c1][d1]*delta[g0][g1] + delta[b0][c0]*delta[b1][d1]*delta[c1][d0]*delta[g0][g1] + delta[b0][c0]*delta[b1][g0]*delta[c1][d0]*delta[d1][g1] + delta[b0][c0]*delta[b1][g0]*delta[c1][d1]*delta[d0][g1] + delta[b0][c0]*delta[b1][g0]*delta[c1][g1]*delta[d0][d1] + delta[b0][c0]*delta[b1][g1]*delta[c1][d0]*delta[d1][g0] + delta[b0][c0]*delta[b1][g1]*delta[c1][d1]*delta[d0][g0] + delta[b0][c0]*delta[b1][g1]*delta[c1][g0]*delta[d0][d1] + delta[b0][c1]*delta[b1][c0]*delta[d0][d1]*delta[g0][g1] + delta[b0][c1]*delta[b1][d0]*delta[c0][d1]*delta[g0][g1] + delta[b0][c1]*delta[b1][d1]*delta[c0][d0]*delta[g0][g1] + delta[b0][c1]*delta[b1][g0]*delta[c0][d0]*delta[d1][g1] + delta[b0][c1]*delta[b1][g0]*delta[c0][d1]*delta[d0][g1] + delta[b0][c1]*delta[b1][g0]*delta[c0][g1]*delta[d0][d1] + delta[b0][c1]*delta[b1][g1]*delta[c0][d0]*delta[d1][g0] + delta[b0][c1]*delta[b1][g1]*delta[c0][d1]*delta[d0][g0] + delta[b0][c1]*delta[b1][g1]*delta[c0][g0]*delta[d0][d1] + delta[b0][d0]*delta[b1][c0]*delta[c1][d1]*delta[g0][g1] + delta[b0][d0]*delta[b1][c1]*delta[c0][d1]*delta[g0][g1] + delta[b0][d0]*delta[b1][d1]*delta[c0][c1]*delta[g0][g1] + delta[b0][d0]*delta[b1][g0]*delta[c0][c1]*d