A_0*PB_0*PB_1*PQ[c1]*PQ[g0]*QC_0*QD_0 - PA_0*PB_0*PB_1*PQ[d0]*PQ[g0]*QC_0*QC_1 - PA_x*PB_0*PB_1*PQ[a0]*PQ[c0]*QC_1*QD_0 - PA_x*PB_0*PB_1*PQ[a0]*PQ[c1]*QC_0*QD_0 - PA_x*PB_0*PB_1*PQ[a0]*PQ[d0]*QC_0*QC_1)

