        const auto r2_PQ = PQ[0] * PQ[0] + PQ[1] * PQ[1] + PQ[2] * PQ[2];

        const auto Lambda = sqrt(4.0 * S1 * S2 * MATH_CONST_INV_PI * inv_S4);

        double F9_t[5];

        gpu::computeBoysFunction(F9_t, S1 * S2 * inv_S4 * r2_PQ, 4, boys_func_table, boys_func_ft);

        const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
        const auto QC_1 = (a_l * inv_S2) * (r_l[c1] - r_k[c1]);
        const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
        const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

        double kl_factor = (static_cast<double>(k != l) + 1.0);

        // mu-nu hessian

        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[4] * S1 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * a_j * (

                        +delta[a0][b0]*delta[c0][c1]*(-PA_x*PB_1*PQ[d0]*PQ[d1]*PQ[g1] - PA_x*PB_1*PQ[d0]*PQ[g1]*QD_1 - PA_x*PB_1*PQ[d1]*PQ[g1]*QD_0 - PA_x*PB_y*PQ[b1]*PQ[d0]*PQ[d1] - PA_x*PB_y*PQ[b1]*PQ[d0]*QD_1 - PA_x*PB_y*PQ[b1]*PQ[d1]*QD_0 + PA_x*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g1] + PA_x*PQ[b1]*PQ[d0]*PQ[g1]*QD_1 + PA_x*PQ[b1]*PQ[d1]*PQ[g1]*QD_0 - PB_1*PB_y*PQ[d0]*PQ[d1]*PQ[g0] - PB_1*PB_y*PQ[d0]*PQ[g0]*QD_1 - PB_1*PB_y*PQ[d1]*PQ[g0]*QD_0 + PB_1*PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1] + PB_1*PQ[d0]*PQ[g0]*PQ[g1]*QD_1 + PB_1*PQ[d1]*PQ[g0]*PQ[g1]*QD_0 + PB_y*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g0] + PB_y*PQ[b1]*PQ[d0]*PQ[g0]*QD_1 + PB_y*PQ[b1]*PQ[d1]*PQ[g0]*QD_0) + delta[a0][b0]*delta[c0][d0]*(-PA_x*PB_1*PQ[c1]*PQ[d1]*PQ[g1] - PA_x*PB_1*PQ[c1]*PQ[g1]*QD_1 - PA_x*PB_1*PQ[d1]*PQ[g1]*QC_1 - PA_x*PB_y*PQ[b1]*PQ[c1]*PQ[d1] - PA_x*PB_y*PQ[b1]*PQ[c1]*QD_1 - PA_x*PB_y*PQ[b1]*PQ[d1]*QC_1 + PA_x*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g1] + PA_x*PQ[b1]*PQ[c1]*PQ[g1]*QD_1 + PA_x*PQ[b1]*PQ[d1]*PQ[g1]*QC_1 - PB_1*PB_y*PQ[c1]*PQ[d1]*PQ[g0] - PB_1*PB_y*PQ[c1]*PQ[g0]*QD_1 - PB_1*PB_y*PQ[d1]*PQ[g0]*QC_1 + PB_1*PQ[c1]*PQ[d1]*PQ[g0]*PQ[g1] + PB_1*PQ[c1]*PQ[g0]*PQ[g1]*QD_1 + PB_1*PQ[d1]*PQ[g0]*PQ[g1]*QC_1 + PB_y*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g0] + PB_y*PQ[b1]*PQ[c1]*PQ[g0]*QD_1 + PB_y*PQ[b1]*PQ[d1]*PQ[g0]*QC_1) + delta[a0][b0]*delta[c0][d1]*(-PA_x*PB_1*PQ[c1]*PQ[d0]*PQ[g1] - PA_x*PB_1*PQ[c1]*PQ[g1]*QD_0 - PA_x*PB_1*PQ[d0]*PQ[g1]*QC_1 - PA_x*PB_y*PQ[b1]*PQ[c1]*PQ[d0] - PA_x*PB_y*PQ[b1]*PQ[c1]*QD_0 - PA_x*PB_y*PQ[b1]*PQ[d0]*QC_1 + PA_x*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g1] + PA_x*PQ[b1]*PQ[c1]*PQ[g1]*QD_0 + PA_x*PQ[b1]*PQ[d0]*PQ[g1]*QC_1 - PB_1*PB_y*PQ[c1]*PQ[d0]*PQ[g0] - PB_1*PB_y*PQ[c1]*PQ[g0]*QD_0 - PB_1*PB_y*PQ[d0]*PQ[g0]*QC_1 + PB_1*PQ[c1]*PQ[d0]*PQ[g0]*PQ[g1] + PB_1*PQ[c1]*PQ[g0]*PQ[g1]*QD_0 + PB_1*PQ[d0]*PQ[g0]*PQ[g1]*QC_1 + PB_y*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g0] + PB_y*PQ[b1]*PQ[c1]*PQ[g0]*QD_0 + PB_y*PQ[b1]*PQ[d0]*PQ[g0]*QC_1) + delta[a0][b0]*delta[c1][d0]*(-PA_x*PB_1*PQ[c0]*PQ[d1]*PQ[g1] - PA_x*PB_1*PQ[c0]*PQ[g1]*QD_1 - PA_x*PB_1*PQ[d1]*PQ[g1]*