                        +(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])*(2.0*PB_y*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 + 2.0*PB_y*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 + 2.0*PB_y*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 + 2.0*PB_y*PQ[c1]*PQ[d0]*PQ[d1]*QC_0 - PQ[c0]*PQ[c1]*PQ[d0]*PQ[g1]*QD_1 - PQ[c0]*PQ[c1]*PQ[d1]*PQ[g1]*QD_0 - PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]*QC_1 - PQ[c1]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0) + (delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1])*(2.0*PA_x*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 + 2.0*PA_x*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 + 2.0*PA_x*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 + 2.0*PA_x*PQ[c1]*PQ[d0]*PQ[d1]*QC_0 - PQ[c0]*PQ[c1]*PQ[d0]*PQ[g0]*QD_1 - PQ[c0]*PQ[c1]*PQ[d1]*PQ[g0]*QD_0 - PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]*QC_1 - PQ[c1]*PQ[d0]*PQ[d1]*PQ[g0]*QC_0) + (delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0])*(2.0*PB_1*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 + 2.0*PB_1*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 + 2.0*PB_1*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 + 2.0*PB_1*PQ[c1]*PQ[d0]*PQ[d1]*QC_0 - PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 - PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 - PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 - PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0) + (delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0])*(2.0*PB_0*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 + 2.0*PB_0*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 + 2.0*PB_0*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 + 2.0*PB_0*PQ[c1]*PQ[d0]*PQ[d1]*QC_0 - PQ[b0]*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 - PQ[b0]*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 - PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 - PQ[b0]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0) + (delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])*(2.0*PA_0*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 + 2.0*PA_0*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 + 2.0*PA_0*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 + 2.0*PA_0*PQ[c1]*PQ[d0]*PQ[d1]*QC_0 - PQ[a0]*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 - PQ[a0]*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 - PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 - PQ[a0]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0)

