                        +(PQ[a0]*PQ[c0]*PQ[g0] + PQ[a0]*PQ[g0]*QC_0)*(delta[b0][c1]*delta[b1][g1]*delta[d0][d1] + delta[b0][d0]*delta[b1][g1]*delta[c1][d1] + delta[b0][d1]*delta[b1][g1]*delta[c1][d0] + delta[b0][g1]*delta[b1][c1]*delta[d0][d1] + delta[b0][g1]*delta[b1][d0]*delta[c1][d1] + delta[b0][g1]*delta[b1][d1]*delta[c1][d0]) + (PQ[a0]*PQ[c1]*PQ[g0] + PQ[a0]*PQ[g0]*QC_1)*(delta[b0][c0]*delta[b1][g1]*delta[d0][d1] + delta[b0][d0]*delta[b1][g1]*delta[c0][d1] + delta[b0][d1]*delta[b1][g1]*delta[c0][d0] + delta[b0][g1]*delta[b1][c0]*delta[d0][d1] + delta[b0][g1]*delta[b1][d0]*delta[c0][d1] + delta[b0][g1]*delta[b1][d1]*delta[c0][d0]) + (PQ[a0]*PQ[d0]*PQ[g0] + PQ[a0]*PQ[g0]*QD_0)*(delta[b0][c0]*delta[b1][g1]*delta[c1][d1] + delta[b0][c1]*delta[b1][g1]*delta[c0][d1] + delta[b0][d1]*delta[b1][g1]*delta[c0][c1] + delta[b0][g1]*delta[b1][c0]*delta[c1][d1] + delta[b0][g1]*delta[b1][c1]*delta[c0][d1] + delta[b0][g1]*delta[b1][d1]*delta[c0][c1]) + (PQ[a0]*PQ[d1]*PQ[g0] + PQ[a0]*PQ[g0]*QD_1)*(delta[b0][c0]*delta[b1][g1]*delta[c1][d0] + delta[b0][c1]*delta[b1][g1]*delta[c0][d0] + delta[b0][d0]*delta[b1][g1]*delta[c0][c1] + delta[b0][g1]*delta[b1][c0]*delta[c1][d0] + delta[b0][g1]*delta[b1][c1]*delta[c0][d0] + delta[b0][g1]*delta[b1][d0]*delta[c0][c1])

