D_1 + PB_0*PQ[a0]*PQ[g0]*PQ[g1]*QC_0*QC_1*QD_1 + PB_y*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QC_1*QD_1) + delta[b1][d1]*(PA_0*PQ[b0]*PQ[g0]*PQ[g1]*QC_0*QC_1*QD_0 + PA_x*PQ[a0]*PQ[b0]*PQ[g1]*QC_0*QC_1*QD_0 + PB_0*PQ[a0]*PQ[g0]*PQ[g1]*QC_0*QC_1*QD_0 + PB_y*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QC_1*QD_0) + delta[c0][g0]*(PA_0*PQ[b0]*PQ[b1]*PQ[g1]*QC_1*QD_0*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g1]*QC_1*QD_0*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g1]*QC_1*QD_0*QD_1 + PB_y*PQ[a0]*PQ[b0]*PQ[b1]*QC_1*QD_0*QD_1) + delta[c0][g1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_1*QD_0*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_1*QD_0*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_1*QD_0*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_1*QD_0*QD_1) + delta[c1][g0]*(PA_0*PQ[b0]*PQ[b1]*PQ[g1]*QC_0*QD_0*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g1]*QC_0*QD_0*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g1]*QC_0*QD_0*QD_1 + PB_y*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QD_0*QD_1) + delta[c1][g1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QD_0*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QD_0*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_0*QD_0*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QD_0*QD_1) + delta[d0][g0]*(PA_0*PQ[b0]*PQ[b1]*PQ[g1]*QC_0*QC_1*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g1]*QC_0*QC_1*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g1]*QC_0*QC_1*QD_1 + PB_y*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QC_1*QD_1) + delta[d0][g1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QC_1*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QC_1*QD_1) + delta[d1][g0]*(PA_0*PQ[b0]*PQ[b1]*PQ[g1]*QC_0*QC_1*QD_0 + PB_0*PQ[a0]*PQ[b1]*PQ[g1]*QC_0*QC_1*QD_0 + PB_1*PQ[a0]*PQ[b0]*PQ[g1]*QC_0*QC_1*QD_0 + PB_y*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QC_1*QD_0) + delta[d1][g1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QD_0 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QC_1*QD_0 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QD_0 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QC_1*QD_0)

