                        +delta[b0][g1]*delta[c0][c1]*(PA_0*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g0] + PA_x*PQ[a0]*PQ[b1]*PQ[d0]*PQ[d1] + PB_1*PQ[a0]*PQ[d0]*PQ[d1]*PQ[g0]) + delta[b0][g1]*delta[c0][d0]*(PA_0*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g0] + PA_x*PQ[a0]*PQ[b1]*PQ[c1]*PQ[d1] + PB_1*PQ[a0]*PQ[c1]*PQ[d1]*PQ[g0]) + delta[b0][g1]*delta[c0][d1]*(PA_0*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g0] + PA_x*PQ[a0]*PQ[b1]*PQ[c1]*PQ[d0] + PB_1*PQ[a0]*PQ[c1]*PQ[d0]*PQ[g0]) + delta[b0][g1]*delta[c1][d0]*(PA_0*PQ[b1]*PQ[c0]*PQ[d1]*PQ[g0] + PA_x*PQ[a0]*PQ[b1]*PQ[c0]*PQ[d1] + PB_1*PQ[a0]*PQ[c0]*PQ[d1]*PQ[g0]) + delta[b0][g1]*delta[c1][d1]*(PA_0*PQ[b1]*PQ[c0]*PQ[d0]*PQ[g0] + PA_x*PQ[a0]*PQ[b1]*PQ[c0]*PQ[d0] + PB_1*PQ[a0]*PQ[c0]*PQ[d0]*PQ[g0]) + delta[b0][g1]*delta[d0][d1]*(PA_0*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g0] + PA_x*PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1] + PB_1*PQ[a0]*PQ[c0]*PQ[c1]*PQ[g0]) + delta[b1][g1]*delta[c0][c1]*(PA_0*PQ[b0]*PQ[d0]*PQ[d1]*PQ[g0] + PA_x*PQ[a0]*PQ[b0]*PQ[d0]*PQ[d1] + PB_0*PQ[a0]*PQ[d0]*PQ[d1]*PQ[g0]) + delta[b1][g1]*delta[c0][d0]*(PA_0*PQ[b0]*PQ[c1]*PQ[d1]*PQ[g0] + PA_x*PQ[a0]*PQ[b0]*PQ[c1]*PQ[d1] + PB_0*PQ[a0]*PQ[c1]*PQ[d1]*PQ[g0]) + delta[b1][g1]*delta[c0][d1]*(PA_0*PQ[b0]*PQ[c1]*PQ[d0]*PQ[g0] + PA_x*PQ[a0]*PQ[b0]*PQ[c1]*PQ[d0] + PB_0*PQ[a0]*PQ[c1]*PQ[d0]*PQ[g0]) + delta[b1][g1]*delta[c1][d0]*(PA_0*PQ[b0]*PQ[c0]*PQ[d1]*PQ[g0] + PA_x*PQ[a0]*PQ[b0]*PQ[c0]*PQ[d1] + PB_0*PQ[a0]*PQ[c0]*PQ[d1]*PQ[g0]) + delta[b1][g1]*delta[c1][d1]*(PA_0*PQ[b0]*PQ[c0]*PQ[d0]*PQ[g0] + PA_x*PQ[a0]*PQ[b0]*PQ[c0]*PQ[d0] + PB_0*PQ[a0]*PQ[c0]*PQ[d0]*PQ[g0]) + delta[b1][g1]*delta[d0][d1]*(PA_0*PQ[b0]*PQ[c0]*PQ[c1]*PQ[g0] + PA_x*PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1] + PB_0*PQ[a0]*PQ[c0]*PQ[c1]*PQ[g0])

                        +delta[a0][g0]*delta[b0][g1]*(PB_1*PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1] - PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]) + delta[a0][g0]*delta[b1][g1]*(PB_0*PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1] - PQ[b0]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1])

