PQ[c0]*PQ[d1]*QC_1 + PB_1*PB_y*PQ[a0]*PQ[b0]*PQ[c1]*PQ[d1]*QC_0) + delta[d0][g1]*(PA_0*PA_x*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*QD_1 + PA_0*PA_x*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d1]*QC_1 + PA_0*PA_x*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d1]*QC_0 + PA_0*PB_0*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g0]*QD_1 + PA_0*PB_0*PQ[b1]*PQ[c0]*PQ[d1]*PQ[g0]*QC_1 + PA_0*PB_0*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g0]*QC_0 + PA_0*PB_1*PQ[b0]*PQ[c0]*PQ[c1]*PQ[g0]*QD_1 + PA_0*PB_1*PQ[b0]*PQ[c0]*PQ[d1]*PQ[g0]*QC_1 + PA_0*PB_1*PQ[b0]*PQ[c1]*PQ[d1]*PQ[g0]*QC_0 + PA_x*PB_0*PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1]*QD_1 + PA_x*PB_0*PQ[a0]*PQ[b1]*PQ[c0]*PQ[d1]*QC_1 + PA_x*PB_0*PQ[a0]*PQ[b1]*PQ[c1]*PQ[d1]*QC_0 + PA_x*PB_1*PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*QD_1 + PA_x*PB_1*PQ[a0]*PQ[b0]*PQ[c0]*PQ[d1]*QC_1 + PA_x*PB_1*PQ[a0]*PQ[b0]*PQ[c1]*PQ[d1]*QC_0 + PB_0*PB_1*PQ[a0]*PQ[c0]*PQ[c1]*PQ[g0]*QD_1 + PB_0*PB_1*PQ[a0]*PQ[c0]*PQ[d1]*PQ[g0]*QC_1 + PB_0*PB_1*PQ[a0]*PQ[c1]*PQ[d1]*PQ[g0]*QC_0) + delta[d1][g0]*(PA_0*PB_0*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g1]*QD_0 + PA_0*PB_0*PQ[b1]*PQ[c0]*PQ[d0]*PQ[g1]*QC_1 + PA_0*PB_0*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g1]*QC_0 + PA_0*PB_1*PQ[b0]*PQ[c0]*PQ[c1]*PQ[g1]*QD_0 + PA_0*PB_1*PQ[b0]*PQ[c0]*PQ[d0]*PQ[g1]*QC_1 + PA_0*PB_1*PQ[b0]*PQ[c1]*PQ[d0]*PQ[g1]*QC_0 + PA_0*PB_y*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*QD_0 + PA_0*PB_y*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*QC_1 + PA_0*PB_y*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*QC_0 + PB_0*PB_1*PQ[a0]*PQ[c0]*PQ[c1]*PQ[g1]*QD_0 + PB_0*PB_1*PQ[a0]*PQ[c0]*PQ[d0]*PQ[g1]*QC_1 + PB_0*PB_1*PQ[a0]*PQ[c1]*PQ[d0]*PQ[g1]*QC_0 + PB_0*PB_y*PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1]*QD_0 + PB_0*PB_y*PQ[a0]*PQ[b1]*PQ[c0]*PQ[d0]*QC_1 + PB_0*PB_y*PQ[a0]*PQ[b1]*PQ[c1]*PQ[d0]*QC_0 + PB_1*PB_y*PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*QD_0 + PB_1*PB_y*PQ[a0]*PQ[b0]*PQ[c0]*PQ[d0]*QC_1 + PB_1*PB_y*PQ[a0]*PQ[b0]*PQ[c1]*PQ[d0]*QC_0) + delta[d1][g1]*(PA_0*PA_x*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*QD_0 + PA_0*PA_x*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*QC_1 + PA_0*PA_x*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*QC_0 + PA_0*PB_0*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g0]*QD_0 + PA_0*PB_0*PQ[b1]*PQ[c0]*PQ[d0]*PQ[g0]*QC_1 + PA_0*PB_0*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g0]*QC_