                    )

                    + F9_t[5] * 2.0 * S1 * S1 * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_j * (

                        +delta[a0][g0]*(PB_0*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[g1]*QD_1 + PB_0*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*PQ[g1]*QD_0 + PB_0*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]*QC_1 + PB_0*PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0 + PB_1*PQ[b0]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[g1]*QD_1 + PB_1*PQ[b0]*PQ[c0]*PQ[c1]*PQ[d1]*PQ[g1]*QD_0 + PB_1*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]*QC_1 + PB_1*PQ[b0]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0 + PB_y*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*QD_1 + PB_y*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*QD_0 + PB_y*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1 + PB_y*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0)

