        ERIs[threadIdx.y][threadIdx.x] += eri_ijkl * dd_mat_D[kl] * kl_factor;

    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < pd_prim_pair_count_local))
    {
        double hess_ik_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM; n++)
        {
            hess_ik_xy += ERIs[n][threadIdx.x];
        }

        atomicAdd(
            hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + i] * natoms + atom_idx_k,
            hess_ik_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }

