                        +(-PQ[c0] - 2*QC_0)*(delta[a0][g0]*delta[b0][b1]*delta[c1][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c1][d1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c1][g1]*delta[d0][d1]) + (-PQ[c1] - 2*QC_1)*(delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[d0][d1]) + (-PQ[d0] - 2*QD_0)*(delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[c1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[c1][d1]) + (-PQ[d1] - 2*QD_1)*(delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[c1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[c1][d0]) + (-PQ[g1] - 2*QC_y)*(delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[c1][d0])

