[d0][g0] + delta[c0][g1]*delta[c1][g0]*delta[d0][d1]) + PA_x*PB_0*PB_1*(delta[a0][c0]*delta[c1][d0]*delta[d1][g1] + delta[a0][c0]*delta[c1][d1]*delta[d0][g1] + delta[a0][c0]*delta[c1][g1]*delta[d0][d1] + delta[a0][c1]*delta[c0][d0]*delta[d1][g1] + delta[a0][c1]*delta[c0][d1]*delta[d0][g1] + delta[a0][c1]*delta[c0][g1]*delta[d0][d1] + delta[a0][d0]*delta[c0][c1]*delta[d1][g1] + delta[a0][d0]*delta[c0][d1]*delta[c1][g1] + delta[a0][d0]*delta[c0][g1]*delta[c1][d1] + delta[a0][d1]*delta[c0][c1]*delta[d0][g1] + delta[a0][d1]*delta[c0][d0]*delta[c1][g1] + delta[a0][d1]*delta[c0][g1]*delta[c1][d0] + delta[a0][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g1]*delta[c0][d1]*delta[c1][d0])

                        -PA_0*PA_x*PQ[c0]*(delta[b0][b1]*delta[c1][d0]*delta[d1][g1] + delta[b0][b1]*delta[c1][d1]*delta[d0][g1] + delta[b0][b1]*delta[c1][g1]*delta[d0][d1]) - PA_0*PA_x*PQ[c1]*(delta[b0][b1]*delta[c0][d0]*delta[d1][g1] + delta[b0][b1]*delta[c0][d1]*delta[d0][g1] + delta[b0][b1]*delta[c0][g1]*delta[d0][d1]) - PA_0*PA_x*PQ[d0]*(delta[b0][b1]*delta[c0][c1]*delta[d1][g1] + delta[b0][b1]*delta[c0][d1]*delta[c1][g1] + delta[b0][b1]*delta[c0][g1]*delta[c1][d1]) - PA_0*PA_x*PQ[d1]*(delta[b0][b1]*delta[c0][c1]*delta[d0][g1] + delta[b0][b1]*delta[c0][d0]*delta[c1][g1] + delta[b0][b1]*delta[c0][g1]*delta[c1][d0]) - PA_0*PA_x*PQ[g1]*(delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[b0][b1]*delta[c0][d1]*delta[c1][d0]) - PA_0*PB_0*PQ[c0]*(delta[b1][g0]*delta[c1][d0]*delta[d1][g1] + delta[b1][g0]*delta[c1][d1]*delta[d0][g1] + delta[b1][g0]*delta[c1][g1]*delta[d0][d1]) - PA_0*PB_0*PQ[c1]*(delta[b1][g0]*delta[c0][d0]*delta[d1][g1] + delta[b1][g0]*delta[c0][d1]*delta[d0][g1] + delta[b1][g0]*delta[c0][g1]*delta[d0][d1]) - PA_0*PB_0*PQ[d0]*(delta[b1][g0]*delta[c0][c1]*delta[d1][g1] + delta[b1][g0]*delta[c0][d1]*delta[c1][g1] + delta[b1][g0]*delta[c0][g1]*delta[c1][d1]) - PA_0*PB_0*PQ[d1]*(delta[b1][g0]*delta[c0][c1]*delta[d0][g1] + delta[b1][g0]*delta[c0][d0]*delta[c1][g1] + delta[b1][g0]*delta[c0][g1]*delta[c1][d0]) - PA_0*PB_0*PQ[g1]*(delta[b1][g0]*delta[c0][c1]*delta[d0][d1] + delta[b1][g0]*delta[c0][d0]*delta[c1][d1] + delta[b1][g0]*delta[c0][d1]*delta[c1][d0]) - PA_0*PB_1*PQ[c0]*(delta[b0][g0]*delta[c1][d0]*delta[d1][g1] + delta[b0][g0]*delta[c1][d1]*delta[d0][g1] + delta[b0][g0]*delta[c1][g1]*delta[d0][d1]) - PA_0*PB_1*PQ[c1]*(delta[b0][g0]*delta[c0][d0]*delta[d1][g1] + delta[b0][g0]*delta[c0][d1]*delta[d0][g1] + delta[b0][g0]*delta[c0][g1]*delta[d0][d1]) - PA_0*PB_1*PQ[d0]*(delta[b0][g0]*delta[c0][c1]*delta[d1][g1] + delta[b0][g0]*delta[c0][d1]*delta[c1][g1] + delta[b0][g0]*delta[c0][g1]*delta[c1][d1]) - PA_0*PB_1*PQ[d1]*(delta[b0][g0]*delta[c0][c1]*delta[d0][g1] + delta[b0][g0]*delta[c0][d0]*delta[c1][g1] + delta[b0][g0]*delta[c0][g1]*delta[c1][d0]) - PA_0*PB_1*PQ[g1]*(delta[b0][g0]*delta[c0][c1]*delta[d0][d1] + delta[b0][g0]*delta[c0][d0]*delta[c1][d1] + delta[b0][g0]*delta[c0][d1]*delta[c1][d0]) - PA_x*PB_0*PQ[c0]*(delta[a0][b1]*delta[c1][d0]*delta[d1][g1] + delta[a0][b1]*delta[c1][d1]*delta[d0][g1] + delta[a0][b1]*delta[c1][g1]*delta[d0][d1]) - PA_x*PB_0*PQ[c1]*(delta[a0][b1]*delta[c0][d0]*delta[d1][g1] + delta[a0][b1]*delta[c0][d1]*delta[d0][g1] + delta[a0][b1]*delta[c0][g1]*delta[d0][d1]) - PA_x*PB_0*PQ[d0]*(delta[a0][b1]*delta[c0][c1]*delta[d1][g1] + delta[a0][b1]*delta[c0][d1]*delta[c1][g1] + delta[a0][b1]*delta[c0][g1]*delta[c1][d1]) - PA_x*PB_0*PQ[d1]*(delta[a0][b1]*delta[c0][c1]*delta[d0][g1] + delta[a0][b1]*delta[c0][d0]*delta[c1][g1] + delta[a0][b1]*delta[c0][g1]*delta[c1][d0]) - PA_x*PB_0*PQ[g1]*(delta[a0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][b1]*delta[c0][d1]*delta[c1][d0]) - PA_x*PB_1*PQ[c0]*(delta[a0][b0]*delta[c1][d0]*delta[d1][g1] + delta[a0][b0]*delta[c1][d1]*delta[d0][g1] + delta[a0][b0]*delta[c1][g1]*delta[d0][d1]) - PA_x*PB_1*PQ[c1]*(delta[a0][b0]*delta[c0][d0]*delta[d1][g1] + delta[a0][b0]*delta[c0][d1]*delta[d0][g1] + delta[a0][b0]*delta[c0][g1]*delta[d0][d1]) - PA_x*PB_1*PQ[d0]*(delta[a0][b0]*delta[c0][c1]*delta[d1][g1] + delta[a0][b0]*delta[c0][d1]*delta[c1][g1] + delta[a0][b0]*delta[c0][g1]*delta[c1][d1]) - PA_x*PB_1*PQ[d1]*(delta[a0][b0]*delta[c0][c1]*delta[d0][g1] + delta[a0][b0]*delta[c0][d0]*delta[c1][g1] + delta[a0][b0]*delta[c0][g1]*delta[c1][d0]) - PA_x*PB_1*PQ[g1]*(delta[a0][b0]*delta[c0][c1]*delta[d0][d1] + delta[a0][b0]*delta[c0][d0]*delta[c1][d1] + delta[a0][b0]*delta[c0][d1]*delta[c1][d0]) - PB_0*PB_1*PQ[c0]*(delta[a0][g0]*delta[c1][d0]*delta[d1][g1] + delta[a0][g0]*delta[c1][d1]*delta[d0][g1] + delta[a0][g0]*delta[c1][g1]*delta[d0][d1]) - PB_0*PB_1*PQ[c1]*(delta[a0][g0]*delta[c0][d0]*delta[d1][g1] + delta[a0][g0]*delta[c0][d1]*delta[d0][g1] + delta[a0][g0]*delta[c0][g1]*delta[d0][d1]) - PB_0*PB_1*PQ[d0]*(delta[a0][g0]*delta[c0][c1]*delta[d1][g1] + delta[a0][g0]*delta[c0][d1]*delta[c1][g1] + delta[a0][g0]*delta[c0][g1]*delta[c1][d1]) - PB_0*PB_1*PQ[d1]*(delta[a0][g0]*delta[c0][c1]*delta[d0][g1] + delta[a0][g0]*delta[c0][d0]*delta[c1][g1] + delta[a0][g0]*delta[c0][g1]*delta[c1][d0]) - PB_0*PB_1*PQ[g1]*(delta[a0][g0]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[c0][d1]*delta[c1][d0])

                    )

                    + F9_t[3] * 0.25 * S1 * S1 * inv_S2 * inv_S2 * inv_S4 * inv_S4 * inv_S4 * a_k * (

                        -PB_0*(delta[a0][g0]*delta[b1][c0]*delta[c1][d0]*delta[d1][g1] + delta[a0][g0]*delta[b1][c0]*delta[c1][d1]*delta[d0][g1] + delta[a0][g0]*delta[b1][c0]*delta[c1][g1]*delta[d0][d1] + delta[a0][g0]*delta[b1][c1]*delta[c0][d0]*delta[d1][g1] + delta[a0][g0]*delta[b1][c1]*delta[c0][d1]*delta[d0][g1] + delta[a0][g0]*delta[b1][c1]*delta[c0][g1]*delta[d0][d1] + delta[a0][g0]*delta[b1][d0]*delta[c0][c1]*delta[d1][g1] + delta[a0][g0]*delta[b1][d0]*delta[c0][d1]*delta[c1][g1] + delta[a0][g0]*delta[b1][d0]*delta[c0][g1]*delta[c1][d1] + delta[a0][g0]*delta[b1][d1]*delta[c0][c1]*delta[d0][g1] + delta[a0][g0]*delta[b1][d1]*delta[c0][d0]*delta[c1][g1] + delta[a0][g0]*delta[b1][d1]*delta[c0][g1]*delta[c1][d0] + delta[a0][g0]*delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b1][g1]*delta[c0][d1]*delta[c1][d0]) - PB_1*(delta[a0][g0]*delta[b0][c0]*delta[c1][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][c0]*delta[c1][d1]*delta[d0][g1] + delta[a0][g0]*delta[b0][c0]*delta[c1][g1]*delta[d0][d1] + delta[a0][g0]*delta[b0][c1]*delta[c0][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][c1]*delta[c0][d1]*delta[d0][g1] + delta[a0][g0]*delta[b0][c1]*delta[c0][g1]*delta[d0][d1] + delta[a0][g0]*delta[b0][d0]*delta[c0][c1]*delta[d1][g1] + delta[a0][g0]*delta[b0][d0]*delta[c0][d1]*delta[c1][g1] + delta[a0][g0]*delta[b0][d0]*delta[c0][g1]*delta[c1][d1] + delta[a0][g0]*delta[b0][d1]*delta[c0][c1]*delta[d0][g1] + delta[a0][g0]*delta[b0][d1]*delta[c0][d0]*delta[c1][g1] + delta[a0][g0]*delta[b0][d1]*delta[c0][g1]*delta[c1][d0] + delta[a0][g0]*delta[b0][g1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b0][g1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b0][g1]*delta[c0][d1]*delta[c1][d0])

                        +PQ[c0]*(delta[a0][g0]*delta[b0][b1]*delta[c1][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c1][d1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c1][g1]*delta[d0][d1]) + PQ[c1]*(delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[d0][d1]) + PQ[d0]*(delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[c1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[c1][d1]) + PQ[d1]*(delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[c1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[c1][d0]) + PQ[g1]*(delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d0][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[c1][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[c1][d0])

                    )


                );

        ERIs[threadIdx.y][threadIdx.x] += eri_ijkl * dd_mat_D[kl] * kl_factor;

    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < pd_prim_pair_count_local))
    {
        double hess_ik_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM; n++)
        {
            hess_ik_xy += ERIs[n][threadIdx.x];
        }

        atomicAdd(
            hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + i] * natoms + atom_idx_k,
            hess_ik_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }

    __syncthreads();

    }
}

