                        +PQ[a0]*PQ[b0]*QC_0*QD_0*QD_1*delta[b1][g0]*delta[c1][g1] + PQ[a0]*PQ[b0]*QC_1*QD_0*QD_1*delta[b1][g0]*delta[c0][g1] + PQ[a0]*PQ[b1]*QC_0*QD_0*QD_1*delta[b0][g0]*delta[c1][g1] + PQ[a0]*PQ[b1]*QC_1*QD_0*QD_1*delta[b0][g0]*delta[c0][g1] + PQ[a0]*PQ[g0]*QC_0*QD_0*QD_1*delta[b0][b1]*delta[c1][g1] + PQ[a0]*PQ[g0]*QC_1*QD_0*QD_1*delta[b0][b1]*delta[c0][g1] + PQ[b0]*PQ[b1]*QC_0*QD_0*QD_1*delta[a0][g0]*delta[c1][g1] + PQ[b0]*PQ[b1]*QC_1*QD_0*QD_1*delta[a0][g0]*delta[c0][g1] + PQ[b0]*PQ[g0]*QC_0*QD_0*QD_1*delta[a0][b1]*delta[c1][g1] + PQ[b0]*PQ[g0]*QC_1*QD_0*QD_1*delta[a0][b1]*delta[c0][g1] + PQ[b1]*PQ[g0]*QC_0*QD_0*QD_1*delta[a0][b0]*delta[c1][g1] + PQ[b1]*PQ[g0]*QC_1*QD_0*QD_1*delta[a0][b0]*delta[c0][g1]

                    )

                    + F9_t[3] * 2.0 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_i * a_k * (

                        +delta[c0][c1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_y*QD_0*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_y*QD_0*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_y*QD_0*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_y*QD_0*QD_1) + delta[c0][d0]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_1*QC_y*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_1*QC_y*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_1*QC_y*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_1*QC_y*QD_1) + delta[c0][d1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_1*QC_y*QD_0 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_1*QC_y*QD_0 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_1*QC_y*QD_0 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_1*QC_y*QD_0) + delta[c0][g1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_1*QD_0*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_1*QD_0*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_1*QD_0*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_1*QD_0*QD_1) + delta[c1][d0]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QC_y*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QC_y*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_0*QC_y*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QC_y*QD_1) + delta[c1][d1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QC_y*QD_0 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QC_y*QD_0 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_0*QC_y*QD_0 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QC_y*QD_0) + delta[c1][g1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QD_0*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QD_0*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_0*QD_0*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QD_0*QD_1) + delta[d0][d1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QC_y + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QC_1*QC_y + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QC_y + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QC_1*QC_y) + delta[d0][g1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QD_1 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QC_1*QD_1 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QD_1 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QC_1*QD_1) + delta[d1][g1]*(PA_0*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QD_0 + PA_x*PQ[a0]*PQ[b0]*PQ[b1]*QC_0*QC_1*QD_0 + PB_0*PQ[a0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QD_0 + PB_1*PQ[a0]*PQ[b0]*PQ[g0]*QC_0*QC_1*QD_0)

