                        +2.0*PQ[c0]*(delta[a0][b0]*delta[b1][g0]*delta[c1][d0]*delta[d1][g1] + delta[a0][b0]*delta[b1][g0]*delta[c1][d1]*delta[d0][g1] + delta[a0][b0]*delta[b1][g0]*delta[c1][g1]*delta[d0][d1] + delta[a0][b1]*delta[b0][g0]*delta[c1][d0]*delta[d1][g1] + delta[a0][b1]*delta[b0][g0]*delta[c1][d1]*delta[d0][g1] + delta[a0][b1]*delta[b0][g0]*delta[c1][g1]*delta[d0][d1] + delta[a0][g0]*delta[b0][b1]*delta[c1][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c1][d1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c1][g1]*delta[d0][d1]) + 2.0*PQ[c1]*(delta[a0][b0]*delta[b1][g0]*delta[c0][d0]*delta[d1][g1] + delta[a0][b0]*delta[b1][g0]*delta[c0][d1]*delta[d0][g1] + delta[a0][b0]*delta[b1][g0]*delta[c0][g1]*delta[d0][d1] + delta[a0][b1]*delta[b0][g0]*delta[c0][d0]*delta[d1][g1] + delta[a0][b1]*delta[b0][g0]*delta[c0][d1]*delta[d0][g1] + delta[a0][b1]*delta[b0][g0]*delta[c0][g1]*delta[d0][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[d0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[d0][d1]) + 2.0*PQ[d0]*(delta[a0][b0]*delta[b1][g0]*delta[c0][c1]*delta[d1][g1] + delta[a0][b0]*delta[b1][g0]*delta[c0][d1]*delta[c1][g1] + delta[a0][b0]*delta[b1][g0]*delta[c0][g1]*delta[c1][d1] + delta[a0][b1]*delta[b0][g0]*delta[c0][c1]*delta[d1][g1] + delta[a0][b1]*delta[b0][g0]*delta[c0][d1]*delta[c1][g1] + delta[a0][b1]*delta[b0][g0]*delta[c0][g1]*delta[c1][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][c1]*delta[d1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1]*delta[c1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1]*delta[c1][d1]) + 2.0*PQ[d1]*(delta[a0][b0]*delta[b1][g0]*delta[c0][c1]*delta[d0][g1] + delta[a0][b0]*delta[b1][g0]*delta[c0][d0]*delta[c1][g1] + delta[a0][b0]*delta[b1][g0]*delta[c0][g1]*delta[c1][d0] + delta[a0][b1]*delta[b0][g0]*delta[c0][c1]*delta[d0][g1] + delta[a0][b1]*delta[b0][g0]*delta[c0][d0]*delta[c1][g1] + delta[a0][b1]*delta[b0][g0]*delta[c0][g1]*delta[c1][d0] + delta[a0][