                        +(delta[a0][b0]*delta[b1][g0]*delta[c0][c1] + delta[a0][b1]*delta[b0][g0]*delta[c0][c1] + delta[a0][g0]*delta[b0][b1]*delta[c0][c1])*(2.0*PQ[d0]*PQ[d1]*PQ[g1] + 2.0*PQ[d0]*PQ[d1]*QC_y + 2.0*PQ[d0]*PQ[g1]*QD_1 + 2.0*PQ[d1]*PQ[g1]*QD_0) + (delta[a0][b0]*delta[b1][g0]*delta[c0][d0] + delta[a0][b1]*delta[b0][g0]*delta[c0][d0] + delta[a0][g0]*delta[b0][b1]*delta[c0][d0])*(2.0*PQ[c1]*PQ[d1]*PQ[g1] + 2.0*PQ[c1]*PQ[d1]*QC_y + 2.0*PQ[c1]*PQ[g1]*QD_1 + 2.0*PQ[d1]*PQ[g1]*QC_1) + (delta[a0][b0]*delta[b1][g0]*delta[c0][d1] + delta[a0][b1]*delta[b0][g0]*delta[c0][d1] + delta[a0][g0]*delta[b0][b1]*delta[c0][d1])*(2.0*PQ[c1]*PQ[d0]*PQ[g1] + 2.0*PQ[c1]*PQ[d0]*QC_y + 2.0*PQ[c1]*PQ[g1]*QD_0 + 2.0*PQ[d0]*PQ[g1]*QC_1) + (delta[a0][b0]*delta[b1][g0]*delta[c0][g1] + delta[a0][b1]*delta[b0][g0]*delta[c0][g1] + delta[a0][g0]*delta[b0][b1]*delta[c0][g1])*(2.0*PQ[c1]*PQ[d0]*PQ[d1] + 2.0*PQ[c1]*PQ[d0]*QD_1 + 2.0*PQ[c1]*PQ[d1]*QD_0 + 2.0*PQ[d0]*PQ[d1]*QC_1) + (delta[a0][b0]*delta[b1][g0]*delta[c1][d0] + delta[a0][b1]*delta[b0][g0]*delta[c1][d0] + delta[a0][g0]*delta[b0][b1]*delta[c1][d0])*(2.0*PQ[c0]*PQ[d1]*PQ[g1] + 2.0*PQ[c0]*PQ[d1]*QC_y + 2.0*PQ[c0]*PQ[g1]*QD_1 + 2.0*PQ[d1]*PQ[g1]*QC_0) + (delta[a0][b0]*delta[b1][g0]*delta[c1][d1] + delta[a0][b1]*delta[b0][g0]*delta[c1][d1] + delta[a0][g0]*delta[b0][b1]*delta[c1][d1])*(2.0*PQ[c0]*PQ[d0]*PQ[g1] + 2.0*PQ[c0]*PQ[d0]*QC_y + 2.0*PQ[c0]*PQ[g1]*QD_0 + 2.0*PQ[d0]*PQ[g1]*QC_0) + (delta[a0][b0]*delta[b1][g0]*delta[c1][g1] + delta[a0][b1]*delta[b0][g0]*delta[c1][g1] + delta[a0][g0]*delta[b0][b1]*delta[c1][g1])*(2.0*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[c0]*PQ[d0]*QD_1 + 2.0*PQ[c0]*PQ[d1]*QD_0 + 2.0*PQ[d0]*PQ[d1]*QC_0) + (delta[a0][b0]*delta[b1][g0]*delta[d0][d1] + delta[a0][b1]*delta[b0][g0]*delta[d0][d1] + delta[a0][g0]*delta[b0][b1]*delta[d0][d1])*(2.0*PQ[c0]*PQ[c1]*PQ[g1] + 2.0*PQ[c0]*PQ[c1]*QC_y + 2.0*PQ[c0]*PQ[g1]*QC_1 + 2.0*PQ[c1]*PQ[g1]*QC_0) + (delta[a0][b0]*delta[b1][g0]*delta[d0][g1] + delta[a0][b1]*delta[b0][g0]*delta[d0][g1] 