*PQ[d0]*PQ[d1]*PQ[g1]*QC_0*QC_1 + PB_1*PQ[a0]*PQ[c0]*PQ[c1]*PQ[d0]*QC_y*QD_1 + PB_1*PQ[a0]*PQ[c0]*PQ[c1]*PQ[d1]*QC_y*QD_0 + PB_1*PQ[a0]*PQ[c0]*PQ[c1]*PQ[g1]*QD_0*QD_1 + PB_1*PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1*QC_y + PB_1*PQ[a0]*PQ[c0]*PQ[d0]*PQ[g1]*QC_1*QD_1 + PB_1*PQ[a0]*PQ[c0]*PQ[d1]*PQ[g1]*QC_1*QD_0 + PB_1*PQ[a0]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0*QC_y + PB_1*PQ[a0]*PQ[c1]*PQ[d0]*PQ[g1]*QC_0*QD_1 + PB_1*PQ[a0]*PQ[c1]*PQ[d1]*PQ[g1]*QC_0*QD_0 + PB_1*PQ[a0]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0*QC_1 - PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*QC_y*QD_1 - PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d1]*QC_y*QD_0 - PQ[a0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[g1]*QD_0*QD_1 - PQ[a0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1*QC_y - PQ[a0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[g1]*QC_1*QD_1 - PQ[a0]*PQ[b1]*PQ[c0]*PQ[d1]*PQ[g1]*QC_1*QD_0 - PQ[a0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0*QC_y - PQ[a0]*PQ[b1]*PQ[c1]*PQ[d0]*PQ[g1]*QC_0*QD_1 - PQ[a0]*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g1]*QC_0*QD_0 - PQ[a0]*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0*QC_1) + delta[b1][g0]*(PA_0*PQ[b0]*PQ[c0]*PQ[c1]*PQ[d0]*QC_y*QD_1 + PA_0*PQ[b0]*PQ[c0]*PQ[c1]*PQ[d1]*QC_y*QD_0 + PA_0*PQ[b0]*PQ[c0]*PQ[c1]*PQ[g1]*QD_0*QD_1 + PA_0*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1*QC_y + PA_0*PQ[b0]*PQ[c0]*PQ[d0]*PQ[g1]*QC_1*QD_1 + PA_0*PQ[b0]*PQ[c0]*PQ[d1]*PQ[g1]*QC_1*QD_0 + PA_0*PQ[b0]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0*QC_y + PA_0*PQ[b0]*PQ[c1]*PQ[d0]*PQ[g1]*QC_0*QD_1 + PA_0*PQ[b0]*PQ[c1]*PQ[d1]*PQ[g1]*QC_0*QD_0 + PA_0*PQ[b0]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0*QC_1 + PB_0*PQ[a0]*PQ[c0]*PQ[c1]*PQ[d0]*QC_y*QD_1 + PB_0*PQ[a0]*PQ[c0]*PQ[c1]*PQ[d1]*QC_y*QD_0 + PB_0*PQ[a0]*PQ[c0]*PQ[c1]*PQ[g1]*QD_0*QD_1 + PB_0*PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1]*QC_1*QC_y + PB_0*PQ[a0]*PQ[c0]*PQ[d0]*PQ[g1]*QC_1*QD_1 + PB_0*PQ[a0]*PQ[c0]*PQ[d1]*PQ[g1]*QC_1*QD_0 + PB_0*PQ[a0]*PQ[c1]*PQ[d0]*PQ[d1]*QC_0*QC_y + PB_0*PQ[a0]*PQ[c1]*PQ[d0]*PQ[g1]*QC_0*QD_1 + PB_0*PQ[a0]*PQ[c1]*PQ[d1]*PQ[g1]*QC_0*QD_0 + PB_0*PQ[a0]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0*QC_1 - PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*PQ[d0]*QC_y*QD_1 - PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*PQ[d1]*QC_y*QD_0 - PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*PQ[g1]*Q