                    )

                    + F9_t[0] * (-0.5) * inv_S1 * inv_S2 * a_k * (

                        +QC_0*QC_1*QC_y*(delta[a0][b0]*delta[b1][g0]*delta[d0][d1] + delta[a0][b1]*delta[b0][g0]*delta[d0][d1]) + QC_0*QC_1*QD_0*(delta[a0][b0]*delta[b1][g0]*delta[d1][g1] + delta[a0][b1]*delta[b0][g0]*delta[d1][g1]) + QC_0*QC_1*QD_1*(delta[a0][b0]*delta[b1][g0]*delta[d0][g1] + delta[a0][b1]*delta[b0][g0]*delta[d0][g1]) + QC_0*QC_y*QD_0*(delta[a0][b0]*delta[b1][g0]*delta[c1][d1] + delta[a0][b1]*delta[b0][g0]*delta[c1][d1]) + QC_0*QC_y*QD_1*(delta[a0][b0]*delta[b1][g0]*delta[c1][d0] + delta[a0][b1]*delta[b0][g0]*delta[c1][d0]) + QC_0*QD_0*QD_1*(delta[a0][b0]*delta[b1][g0]*delta[c1][g1] + delta[a0][b1]*delta[b0][g0]*delta[c1][g1]) + QC_1*QC_y*QD_0*(delta[a0][b0]*delta[b1][g0]*delta[c0][d1] + delta[a0][b1]*delta[b0][g0]*delta[c0][d1]) + QC_1*QC_y*QD_1*(delta[a0][b0]*delta[b1][g0]*delta[c0][d0] + delta[a0][b1]*delta[b0][g0]*delta[c0][d0]) + QC_1*QD_0*QD_1*(delta[a0][b0]*delta[b1][g0]*delta[c0][g1] + delta[a0][b1]*delta[b0][g0]*delta[c0][g1]) + QC_y*QD_0*QD_1*(delta[a0][b0]*delta[b1][g0]*delta[c0][c1] + delta[a0][b1]*delta[b0][g0]*delta[c0][c1])

