                        +PA_0*PB_0*QC_0*(delta[b1][g0]*delta[c1][d0]*delta[d1][g1] + delta[b1][g0]*delta[c1][d1]*delta[d0][g1] + delta[b1][g0]*delta[c1][g1]*delta[d0][d1]) + PA_0*PB_0*QC_1*(delta[b1][g0]*delta[c0][d0]*delta[d1][g1] + delta[b1][g0]*delta[c0][d1]*delta[d0][g1] + delta[b1][g0]*delta[c0][g1]*delta[d0][d1]) + PA_0*PB_0*QC_y*(delta[b1][g0]*delta[c0][c1]*delta[d0][d1] + delta[b1][g0]*delta[c0][d0]*delta[c1][d1] + delta[b1][g0]*delta[c0][d1]*delta[c1][d0]) + PA_0*PB_0*QD_0*(delta[b1][g0]*delta[c0][c1]*delta[d1][g1] + delta[b1][g0]*delta[c0][d1]*delta[c1][g1] + delta[b1][g0]*delta[c0][g1]*delta[c1][d1]) + PA_0*PB_0*QD_1*(delta[b1][g0]*delta[c0][c1]*delta[d0][g1] + delta[b1][g0]*delta[c0][d0]*delta[c1][g1] + delta[b1][g0]*delta[c0][g1]*delta[c1][d0]) + PA_0*PB_1*QC_0*(delta[b0][g0]*delta[c1][d0]*delta[d1][g1] + delta[b0][g0]*delta[c1][d1]*delta[d0][g1] + delta[b0][g0]*delta[c1][g1]*delta[d0][d1]) + PA_0*PB_1*QC_1*(delta[b0][g0]*delta[c0][d0]*delta[d1][g1] + delta[b0][g0]*delta[c0][d1]*delta[d0][g1] + delta[b0][g0]*delta[c0][g1]*delta[d0][d1]) + PA_0*PB_1*QC_y*(delta[b0][g0]*delta[c0][c1]*delta[d0][d1] + delta[b0][g0]*delta[c0][d0]*delta[c1][d1] + delta[b0][g0]*delta[c0][d1]*delta[c1][d0]) + PA_0*PB_1*QD_0*(delta[b0][g0]*delta[c0][c1]*delta[d1][g1] + delta[b0][g0]*delta[c0][d1]*delta[c1][g1] + delta[b0][g0]*delta[c0][g1]*delta[c1][d1]) + PA_0*PB_1*QD_1*(delta[b0][g0]*delta[c0][c1]*delta[d0][g1] + delta[b0][g0]*delta[c0][d0]*delta[c1][g1] + delta[b0][g0]*delta[c0][g1]*delta[c1][d0])

