                        +(delta[a0][b0]*delta[b1][c0] + delta[a0][b1]*delta[b0][c0] + delta[a0][c0]*delta[b0][b1])*(-PB_x*PQ[c1]*QC_y*QD_0*QD_1 - PB_x*PQ[d0]*QC_1*QC_y*QD_1 - PB_x*PQ[d1]*QC_1*QC_y*QD_0 - PB_x*PQ[g1]*QC_1*QD_0*QD_1) + (delta[a0][b0]*delta[b1][c1] + delta[a0][b1]*delta[b0][c1] + delta[a0][c1]*delta[b0][b1])*(-PB_x*PQ[c0]*QC_y*QD_0*QD_1 - PB_x*PQ[d0]*QC_0*QC_y*QD_1 - PB_x*PQ[d1]*QC_0*QC_y*QD_0 - PB_x*PQ[g1]*QC_0*QD_0*QD_1) + (delta[a0][b0]*delta[b1][d0] + delta[a0][b1]*delta[b0][d0] + delta[a0][d0]*delta[b0][b1])*(-PB_x*PQ[c0]*QC_1*QC_y*QD_1 - PB_x*PQ[c1]*QC_0*QC_y*QD_1 - PB_x*PQ[d1]*QC_0*QC_1*QC_y - PB_x*PQ[g1]*QC_0*QC_1*QD_1) + (delta[a0][b0]*delta[b1][d1] + delta[a0][b1]*delta[b0][d1] + delta[a0][d1]*delta[b0][b1])*(-PB_x*PQ[c0]*QC_1*QC_y*QD_0 - PB_x*PQ[c1]*QC_0*QC_y*QD_0 - PB_x*PQ[d0]*QC_0*QC_1*QC_y - PB_x*PQ[g1]*QC_0*QC_1*QD_0) + (delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1])*(-PB_x*PQ[c0]*QC_1*QD_0*QD_1 - PB_x*PQ[c1]*QC_0*QD_0*QD_1 - PB_x*PQ[d0]*QC_0*QC_1*QD_1 - PB_x*PQ[d1]*QC_0*QC_1*QD_0) + (delta[a0][b0]*delta[c0][g0] + delta[a0][c0]*delta[b0][g0] + delta[a0][g0]*delta[b0][c0])*(-PB_1*PQ[c1]*QC_y*QD_0*QD_1 - PB_1*PQ[d0]*QC_1*QC_y*QD_1 - PB_1*PQ[d1]*QC_1*QC_y*QD_0 - PB_1*PQ[g1]*QC_1*QD_0*QD_1) + (delta[a0][b0]*delta[c1][g0] + delta[a0][c1]*delta[b0][g0] + delta[a0][g0]*delta[b0][c1])*(-PB_1*PQ[c0]*QC_y*QD_0*QD_1 - PB_1*PQ[d0]*QC_0*QC_y*QD_1 - PB_1*PQ[d1]*QC_0*QC_y*QD_0 - PB_1*PQ[g1]*QC_0*QD_0*QD_1) + (delta[a0][b0]*delta[d0][g0] + delta[a0][d0]*delta[b0][g0] + delta[a0][g0]*delta[b0][d0])*(-PB_1*PQ[c0]*QC_1*QC_y*QD_1 - PB_1*PQ[c1]*QC_0*QC_y*QD_1 - PB_1*PQ[d1]*QC_0*QC_1*QC_y - PB_1*PQ[g1]*QC_0*QC_1*QD_1) + (delta[a0][b0]*delta[d1][g0] + delta[a0][d1]*delta[b0][g0] + delta[a0][g0]*delta[b0][d1])*(-PB_1*PQ[c0]*QC_1*QC_y*QD_0 - PB_1*PQ[c1]*QC_0*QC_y*QD_0 - PB_1*PQ[d0]*QC_0*QC_1*QC_y - PB_1*PQ[g1]*QC_0*QC_1*QD_0) + (delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0])*(-PB