        double F9_t[4];

        gpu::computeBoysFunction(F9_t, S1 * S2 * inv_S4 * r2_PQ, 3, boys_func_table, boys_func_ft);

        const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
        const auto QC_1 = (a_l * inv_S2) * (r_l[c1] - r_k[c1]);
        const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
        const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

        const auto QC_y = (a_l * inv_S2) * (r_l[g1] - r_k[g1]);

        double kl_factor = (static_cast<double>(k != l) + 1.0);

        // nu-lambda hessian

        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[3] * 0.5 * S1 * inv_S2 * inv_S4 * inv_S4 * inv_S4 * a_j * a_k * (

                        +(-2*PA_0*PB_0*PQ[b1] - 2*PA_0*PB_1*PQ[b0] - 2*PB_0*PB_1*PQ[a0])*(delta[c0][c1]*delta[d0][d1]*delta[g0][g1] + delta[c0][c1]*delta[d0][g0]*delta[d1][g1] + delta[c0][c1]*delta[d0][g1]*delta[d1][g0] + delta[c0][d0]*delta[c1][d1]*delta[g0][g1] + delta[c0][d0]*delta[c1][g0]*delta[d1][g1] + delta[c0][d0]*delta[c1][g1]*delta[d1][g0] + delta[c0][d1]*delta[c1][d0]*delta[g0][g1] + delta[c0][d1]*delta[c1][g0]*delta[d0][g1] + delta[c0][d1]*delta[c1][g1]*delta[d0][g0] + delta[c0][g0]*delta[c1][d0]*delta[d1][g1] + delta[c0][g0]*delta[c1][d1]*delta[d0][g1] + delta[c0][g0]*delta[c1][g1]*delta[d0][d1] + delta[c0][g1]*delta[c1][d0]*delta[d1][g0] + delta[c0][g1]*delta[c1][d1]*delta[d0][g0] + delta[c0][g1]*delta[c1][g0]*delta[d0][d1]) + (-2*PA_0*PB_0*PQ[g0] - 2*PA_0*PB_x*PQ[b0] - 2*PB_0*PB_x*PQ[a0])*(delta[b1][c0]*delta[c1][d0]*delta[d1][g1] + delta[b1][c0]*delta[c1][d1]*delta[d0][g1] + delta[b1][c0]*delta[c1][g1]*delta[d0][d1] + delta[b1][c1]*delta[c0][d0]*delta[d1][g1] + delta[b1][c1]*delta[c0][d1]*delta[d0][g1] + delta[b1][c1]*delta[c0][g1]*delta[d0][d1] + delta[b1][d0]*delta[c0][c1]*delta[d1][g1] + delta[b1][d0]*delta[c0][d1]*delta[c1][g1] + delta[b1][d0]*delta[c0][g1]*delta[c1][d1] + delta[b1][d1]*delta[c0][c1]*delta[d0][g1] + delta[b1][d1]*delta[c0][d0]*delta[c1][g1] + delta[b1][d1]*delta[c0][g1]*delta[c1][d0] + delta[b1][g1]*delta[c0][c1]*delta[d0][d1] + delta[b1][g1]*delta[c0][d0]*delta[c1][d1] + delta[b1][g1]*delta[c0][d1]*delta[c1][d0]) + (-2*PA_0*PB_1*PQ[g0] - 2*PA_0*PB_x*PQ[b1] - 2*PB_1*PB_x*PQ[a0])*(delta[b0][c0]*delta[c1][d0]*delta[d1][g1] + delta[b0][c0]*delta[c1][d1]*delta[d0][g1] + delta[b0][c0]*delta[c1][g1]*delta[d0][d1] + delta[b0][c1]*delta[c0][d0]*delta[d1][g1] + delta[b0][c1]*delta[c0][d1]*delta[d0][g1] + delta[b0][c1]*delta[c0][g1]*delta[d0][d1] + delta[b0][d0]*delta[c0][c1]*delta[d1][g1] + delta[b0][d0]*delta[c0][d1]*delta[c1][g1] + delta[b0][d0]*delta[c0][g1]*delta[c1][d1] + delta[b0][d1]*delta[c0][c1]*delta[d0][g1] + delta[b0][d1]*delt