                        +delta[a0][b0]*(-PB_1*PB_x*PQ[c0]*PQ[c1]*PQ[d0]*QC_y*QD_1 - PB_1*PB_x*PQ[c0]*PQ[c1]*PQ[d1]*QC_y*QD_0 - PB_1*PB_x*PQ[c0]*PQ[c1]*PQ[g1]*QD_0*QD_1 - PB_1*PB_x*PQ[c0]*PQ[d0]*PQ[d1]*QC_1*QC_y - PB_1*PB_x*PQ[c0]*PQ[d0]*PQ[g1]*QC_1*QD_1 - PB_1*PB_x*PQ[c0]*PQ[d1]*PQ[g1]*QC_1*QD_0 - PB_1*PB_x*PQ[c1]*PQ[d0]*PQ[d1]*QC_0*QC_y - PB_1*PB_x*PQ[c1]*PQ[d0]*PQ[g1]*QC_0*QD_1 - PB_1*PB_x*PQ[c1]*PQ[d1]*PQ[g1]*QC_0*QD_0 - PB_1*PB_x*PQ[d0]*PQ[d1]*PQ[g1]*QC_0*QC_1) + delta[a0][b1]*(-PB_0*PB_x*PQ[c0]*PQ[c1]*PQ[d0]*QC_y*QD_1 - PB_0*PB_x*PQ[c0]*PQ[c1]*PQ[d1]*QC_y*QD_0 - PB_0*PB_x*PQ[c0]*PQ[c1]*PQ[g1]*QD_0*QD_1 - PB_0*PB_x*PQ[c0]*PQ[d0]*PQ[d1]*QC_1*QC_y - PB_0*PB_x*PQ[c0]*PQ[d0]*PQ[g1]*QC_1*QD_1 - PB_0*PB_x*PQ[c0]*PQ[d1]*PQ[g1]*QC_1*QD_0 - PB_0*PB_x*PQ[c1]*PQ[d0]*PQ[d1]*QC_0*QC_y - PB_0*PB_x*PQ[c1]*PQ[d0]*PQ[g1]*QC_0*QD_1 - PB_0*PB_x*PQ[c1]*PQ[d1]*PQ[g1]*QC_0*QD_0 - PB_0*PB_x*PQ[d0]*PQ[d1]*PQ[g1]*QC_0*QC_1) + delta[a0][g0]*(-PB_0*PB_1*PQ[c0]*PQ[c1]*PQ[d0]*QC_y*QD_1 - PB_0*PB_1*PQ[c0]*PQ[c1]*PQ[d1]*QC_y*QD_0 - PB_0*PB_1*PQ[c0]*PQ[c1]*PQ[g1]*QD_0*QD_1 - PB_0*PB_1*PQ[c0]*PQ[d0]*PQ[d1]*QC_1*QC_y - PB_0*PB_1*PQ[c0]*PQ[d0]*PQ[g1]*QC_1*QD_1 - PB_0*PB_1*PQ[c0]*PQ[d1]*PQ[g1]*QC_1*QD_0 - PB_0*PB_1*PQ[c1]*PQ[d0]*PQ[d1]*QC_0*QC_y - PB_0*PB_1*PQ[c1]*PQ[d0]*PQ[g1]*QC_0*QD_1 - PB_0*PB_1*PQ[c1]*PQ[d1]*PQ[g1]*QC_0*QD_0 - PB_0*PB_1*PQ[d0]*PQ[d1]*PQ[g1]*QC_0*QC_1) + delta[b0][b1]*(-PA_0*PB_x*PQ[c0]*PQ[c1]*PQ[d0]*QC_y*QD_1 - PA_0*PB_x*PQ[c0]*PQ[c1]*PQ[d1]*QC_y*QD_0 - PA_0*PB_x*PQ[c0]*PQ[c1]*PQ[g1]*QD_0*QD_1 - PA_0*PB_x*PQ[c0]*PQ[d0]*PQ[d1]*QC_1*QC_y - PA_0*PB_x*PQ[c0]*PQ[d0]*PQ[g1]*QC_1*QD_1 - PA_0*PB_x*PQ[c0]*PQ[d1]*PQ[g1]*QC_1*QD_0 - PA_0*PB_x*PQ[c1]*PQ[d0]*PQ[d1]*QC_0*QC_y - PA_0*PB_x*PQ[c1]*PQ[d0]*PQ[g1]*QC_0*QD_1 - PA_0*PB_x*PQ[c1]*PQ[d1]*PQ[g1]*QC_0*QD_0 - PA_0*PB_x*PQ[d0]*PQ[d1]*PQ[g1]*QC_0*QC_1) + delta[b0][g0]*(-PA_0*PB_1*PQ[c0]*PQ[c1]*PQ[d0]*QC_y*QD_1 - PA_0*PB_1*PQ[c0]*PQ[c1]*PQ[d1]*QC_y*QD_0 - PA_0*PB_1*PQ[c0]*PQ[c1]*PQ[g1]*QD_0*QD_1 - PA_0*PB_1*PQ[c0]*PQ[d0]*PQ[d1]*QC_1*QC_y -