        const auto Lambda = sqrt(4.0 * S1 * S2 * MATH_CONST_INV_PI * inv_S4);

        double F9_t[6];

        gpu::computeBoysFunction(F9_t, S1 * S2 * inv_S4 * r2_PQ, 5, boys_func_table, boys_func_ft);

        const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
        const auto QC_1 = (a_l * inv_S2) * (r_l[c1] - r_k[c1]);
        const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
        const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

        const auto QC_y = (a_l * inv_S2) * (r_l[g1] - r_k[g1]);

        double kl_factor = (static_cast<double>(k != l) + 1.0);

        // nu-lambda hessian

        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[5] * S1 * S1 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_j * a_k * (

                        +(delta[a0][c0]*delta[c1][d0] + delta[a0][c1]*delta[c0][d0] + delta[a0][d0]*delta[c0][c1])*(PB_0*PQ[b1]*PQ[d1]*PQ[g0]*PQ[g1] + PB_0*PQ[b1]*PQ[d1]*PQ[g0]*QC_y + PB_0*PQ[b1]*PQ[g0]*PQ[g1]*QD_1 + PB_1*PQ[b0]*PQ[d1]*PQ[g0]*PQ[g1] + PB_1*PQ[b0]*PQ[d1]*PQ[g0]*QC_y + PB_1*PQ[b0]*PQ[g0]*PQ[g1]*QD_1 + PB_x*PQ[b0]*PQ[b1]*PQ[d1]*PQ[g1] + PB_x*PQ[b0]*PQ[b1]*PQ[d1]*QC_y + PB_x*PQ[b0]*PQ[b1]*PQ[g1]*QD_1) + (delta[a0][c0]*delta[c1][d1] + delta[a0][c1]*delta[c0][d1] + delta[a0][d1]*delta[c0][c1])*(PB_0*PQ[b1]*PQ[d0]*PQ[g0]*PQ[g1] + PB_0*PQ[b1]*PQ[d0]*PQ[g0]*QC_y + PB_0*PQ[b1]*PQ[g0]*PQ[g1]*QD_0 + PB_1*PQ[b0]*PQ[d0]*PQ[g0]*PQ[g1] + PB_1*PQ[b0]*PQ[d0]*PQ[g0]*QC_y + PB_1*PQ[b0]*PQ[g0]*PQ[g1]*QD_0 + PB_x*PQ[b0]*PQ[b1]*PQ[d0]*PQ[g1] + PB_x*PQ[b0]*PQ[b1]*PQ[d0]*QC_y + PB_x*PQ[b0]*PQ[b1]*PQ[g1]*QD_0) + (delta[a0][c0]*delta[c1][g1] + delta[a0][c1]*delta[c0][g1] + delta[a0][g1]*delta[c0][c1])*(PB_0*PQ[b1]*PQ[d0]*PQ[d1]*PQ[g0] + PB_0*PQ[b1]*PQ[d0]*PQ[g0]*QD_1 + PB_0*PQ[b1]*PQ[d1]*PQ[g0]*QD_0 + PB_1*PQ[b0]*PQ[d0]*PQ[d1]*PQ[g0] + PB_1*PQ[b0]*PQ[d0]*PQ[g0]*QD_1 + PB_1*PQ[b0]*PQ[d1]*PQ[g0]*QD_0 + PB_x*PQ[b0]*PQ[b1]*PQ[d0]*PQ[d1] + PB_x*PQ[b0]*PQ[b1]*PQ[d0]*QD_1 + PB_x*PQ[b0]*PQ[b1]*PQ[d1]*QD_0) + (delta[a0][c0]*delta[d0][d1] + delta[a0][d0]*delta[c0][d1] + delta[a0][d1]*delta[c0][d0])*(PB_0*PQ[b1]*PQ[c1]*PQ[g0]*PQ[g1] + PB_0*PQ[b1]*PQ[c1]*PQ[g0]*QC_y + PB_0*PQ[b1]*PQ[g0]*PQ[g1]*QC_1 + PB_1*PQ[b0]*PQ[c1]*PQ[g0]*PQ[g1] + PB_1*PQ[b0]*PQ[c1]*PQ[g0]*QC_y + PB_1*PQ[b0]*PQ[g0]*PQ[g1]*QC_1 + PB_x*PQ[b0]*PQ[b1]*PQ[c1]*PQ[g1] + PB_x*PQ[b0]*PQ[b1]*PQ[c1]*QC_y + PB_x*PQ[b0]*PQ[b1]*PQ[g1]*QC_1) + (delta[a0][c0]*delta[d0][g1] + delta[a0][d0]*delta[c0][g1] + delta[a0][g1]*delta[c0][d0])*(PB_0*PQ[b1]*PQ[c1]*PQ[d1]*PQ[g0] + PB_0*PQ[b1]*PQ[c1]*PQ[g0]*QD_1 + PB_0*PQ[b1]*PQ[d1]*PQ[g0]*QC_1 + PB_1*PQ[b0]*PQ[c1]*PQ[d1]*PQ[g0] + PB_1*PQ[b0]*PQ[c1]*PQ[g0]*QD_1 + PB_1*PQ[b0]*PQ[d1]*PQ[g0]*QC_1 + PB_x*PQ[b0]*PQ[b1]*PQ[c1]*PQ[d1] + PB_x*PQ[b0]*PQ[b1]*PQ[c1]*QD_1 + PB_x*PQ[b0]*PQ[b1]*PQ[d1]*QC_1) + 