                    )

                    + F9_t[1] * (-2.0) * S1 * inv_S2 * inv_S4 * a_i * a_l * (

                        +delta[c0][c1]*(PA_0*PA_x*PB_0*PB_1*PQ[d0]*QD_1*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[d1]*QD_0*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[g1]*QD_0*QD_1 + PA_0*PA_x*PB_0*PB_1*QD_0*QD_1*QD_y) + delta[c0][d0]*(PA_0*PA_x*PB_0*PB_1*PQ[c1]*QD_1*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[d1]*QC_1*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[g1]*QC_1*QD_1 + PA_0*PA_x*PB_0*PB_1*QC_1*QD_1*QD_y) + delta[c0][d1]*(PA_0*PA_x*PB_0*PB_1*PQ[c1]*QD_0*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[d0]*QC_1*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[g1]*QC_1*QD_0 + PA_0*PA_x*PB_0*PB_1*QC_1*QD_0*QD_y) + delta[c0][g1]*(PA_0*PA_x*PB_0*PB_1*PQ[c1]*QD_0*QD_1 + PA_0*PA_x*PB_0*PB_1*PQ[d0]*QC_1*QD_1 + PA_0*PA_x*PB_0*PB_1*PQ[d1]*QC_1*QD_0 + PA_0*PA_x*PB_0*PB_1*QC_1*QD_0*QD_1) + delta[c1][d0]*(PA_0*PA_x*PB_0*PB_1*PQ[c0]*QD_1*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[d1]*QC_0*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[g1]*QC_0*QD_1 + PA_0*PA_x*PB_0*PB_1*QC_0*QD_1*QD_y) + delta[c1][d1]*(PA_0*PA_x*PB_0*PB_1*PQ[c0]*QD_0*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[d0]*QC_0*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[g1]*QC_0*QD_0 + PA_0*PA_x*PB_0*PB_1*QC_0*QD_0*QD_y) + delta[c1][g1]*(PA_0*PA_x*PB_0*PB_1*PQ[c0]*QD_0*QD_1 + PA_0*PA_x*PB_0*PB_1*PQ[d0]*QC_0*QD_1 + PA_0*PA_x*PB_0*PB_1*PQ[d1]*QC_0*QD_0 + PA_0*PA_x*PB_0*PB_1*QC_0*QD_0*QD_1) + delta[d0][d1]*(PA_0*PA_x*PB_0*PB_1*PQ[c0]*QC_1*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[c1]*QC_0*QD_y + PA_0*PA_x*PB_0*PB_1*PQ[g1]*QC_0*QC_1 + PA_0*PA_x*PB_0*PB_1*QC_0*QC_1*QD_y) + delta[d0][g1]*(PA_0*PA_x*PB_0*PB_1*PQ[c0]*QC_1*QD_1 + PA_0*PA_x*PB_0*PB_1*PQ[c1]*QC_0*QD_1 + PA_0*PA_x*PB_0*PB_1*PQ[d1]*QC_0*QC_1 + PA_0*PA_x*PB_0*PB_1*QC_0*QC_1*QD_1) + delta[d1][g1]*(PA_0*PA_x*PB_0*PB_1*PQ[c0]*QC_1*QD_0 + PA_0*PA_x*PB_0*PB_1*PQ[c1]*QC_0*QD_0 + PA_0*PA_x*PB_0*PB_1*PQ[d0]*QC_0*QC_1 + PA_0*PA_x*PB_0*PB_1*QC_0*QC_1*QD_0)

                    )

                    + F9_t[1] * S1 * inv_S2 * inv_S4 * a_i * (

                        +(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1])*(PA_0*PA_x*PB_0*PB_1*PQ[c1] + PA_0*PA_x*PB_0*PB_1*QC_1) + (delta[c1][d0]*delta[d1][g1] + delta[c1][d1]*delta[d0][g1])*(PA_0*PA_x*PB_0*PB_1*PQ[c0] + PA_0*PA_x*PB_0*PB_1*QC_0)

                        +delta[c0][c1]*delta[d0][g1]*(PA_0*PA_x*PB_0*PB_1*PQ[d1] + PA_0*PA_x*PB_0*PB_1*QD_1) + delta[c0][c1]*delta[d1][g1]*(PA_0*PA_x*PB_0*PB_1*PQ[d0] + PA_0*PA_x*PB_0*PB_1*QD_0)

                    )

                    + F9_t[1] * S1 * inv_S2 * inv_S4 * a_l * (

                        +delta[a0][g0]*delta[c0][c1]*(PB_0*PB_1*PQ[d0]*QD_1*QD_y + PB_0*PB_1*PQ[d1]*QD_0*QD_y + PB_0*PB_1*PQ[g1]*QD_0*QD_1 + PB_0*PB_1*QD_0*QD_1*QD_y) + delta[a0][g0]*delta[c0][d0]*(PB_0*PB_1*PQ[c1]*QD_1*QD_y + PB_0*PB_1*PQ[d1]*QC_1*QD_y + PB_0*PB_1*PQ[g1]*QC_1*QD_1 + PB_0*PB_1*QC_1*QD_1*QD_y) + delta[a0][g0]*delta[c0][d1]*(PB_0*PB_1*PQ[c1]*QD_0*QD_y + PB_0*PB_1*PQ[d0]*QC_1*QD_y + PB_0*PB_1*PQ[g1]*QC_1*QD_0 + PB_0*PB_1*QC_1*QD_0*QD_y) + delta[a0][g0]*delta[c0][g1]*(PB_0*PB_1*PQ[c1]*QD_0*QD_1 + PB_0*PB_1*PQ[d0]*QC_1*QD_1 + PB_0*PB_1*PQ[d1]*QC_1*QD_0 + PB_0*PB_1*QC_1*QD_0*QD_1) + delta[a0][g0]*delta[c1][d0]*(PB_0*PB_1*PQ[c0]*QD_1*QD_y + PB_0*PB_1*PQ[d1]*QC_0*QD_y + PB_0*PB_1*PQ[g1]*QC_0*QD_1 + PB_0*PB_1*QC_0*QD_1*QD_y) + delta[a0][g0]*delta[c1][d1]*(PB_0*PB_1*PQ[c0]*QD_0*QD_y + PB_0*PB_1*PQ[d0]*QC_0*QD_y + PB_0*PB_1*PQ[g1]*QC_0*QD_0 + PB_0*PB_1*QC_0*QD_0*QD_y) + delta[a0][g0]*delta[c1][g1]*(PB_0*PB_1*PQ[c0]*QD_0*QD_1 + PB_0*PB_1*PQ[d0]*QC_0*QD_1 + PB_0*PB_1*PQ[d1]*QC_0*QD_0 + PB_0*PB_1*QC_0*QD_0*QD_1) + delta[a0][g0]*delta[d0][d1]*(PB_0*PB_1*PQ[c0]*QC_1*QD_y + PB_0*PB_1*PQ[c1]*QC_0*QD_y + PB_0*PB_1*PQ[g1]*QC_0*QC_1 + PB_0*PB_1*QC_0*QC_1*QD_y) + delta[a0][g0]*delta[d0][g1]*(PB_0*PB_1*PQ[c0]*QC_1*QD_1 + PB_0*PB_1*PQ[c1]*QC_0*QD_1 + PB_0*PB_1*PQ[d1]*QC_0*QC_1 + PB_0*PB_1*QC_0*QC_1*QD_1) + delta[a0][g0]*delta[d1][g1]*(PB_0*PB_1*PQ[c0]*QC_1*QD_0 + PB_0*PB_1*PQ[c1]*QC_0*QD_0 + PB_0*PB_1*PQ[d0]*QC_0*QC_1 + PB_0*PB_1*QC_0*QC_1*QD_0)

                    )

                    + F9_t[1] * (-0.5) * S1 * inv_S2 * inv_S4 * (

                        +(PB_0*PB_1*PQ[c0] + PB_0*PB_1*QC_0)*(delta[a0][g0]*delta[c1][d0]*delta[d1][g1] + delta[a0][g0]*delta[c1][d1]*delta[d0][g1]) + (PB_0*PB_1*PQ[c1] + PB_0*PB_1*QC_1)*(delta[a0][g0]*delta[c0][d0]*delta[d1][g1] + delta[a0][g0]*delta[c0][d1]*delta[d0][g1])

                        +delta[a0][g0]*delta[c0][c1]*delta[d0][g1]*(PB_0*PB_1*PQ[d1] + PB_0*PB_1*QD_1) + delta[a0][g0]*delta[c0][c1]*delta[d1][g1]*(PB_0*PB_1*PQ[d0] + PB_0*PB_1*QD_0)

                    )

                    + F9_t[1] * 2.0 * S2 * inv_S1 * inv_S4 * a_i * a_l * (

                        +delta[a0][b0]*(-PA_x*PB_1*QC_0*QC_1*QD_0*QD_1*QD_y + PA_x*PQ[b1]*QC_0*QC_1*QD_0*QD_1*QD_y + PB_1*PQ[g0]*QC_0*QC_1*QD_0*QD_1*QD_y) + delta[a0][b1]*(-PA_x*PB_0*QC_0*QC_1*QD_0*QD_1*QD_y + PA_x*PQ[b0]*QC_0*QC_1*QD_0*QD_1*QD_y + PB_0*PQ[g0]*QC_0*QC_1*QD_0*QD_1*QD_y) + delta[a0][g0]*(-PB_0*PB_1*QC_0*QC_1*QD_0*QD_1*QD_y + PB_0*PQ[b1]*QC_0*QC_1*QD_0*QD_1*QD_y + PB_1*PQ[b0]*QC_0*QC_1*QD_0*QD_1*QD_y) + delta[b0][b1]*(-PA_0*PA_x*QC_0*QC_1*QD_0*QD_1*QD_y + PA_0*PQ[g0]*QC_0*QC_1*QD_0*QD_1*QD_y + PA_x*PQ[a0]*QC_0*QC_1*QD_0*QD_1*QD_y) + delta[b0][g0]*(-PA_0*PB_1*QC_0*QC_1*QD_0*QD_1*QD_y + PA_0*PQ[b1]*QC_0*QC_1*QD_0*QD_1*QD_y + PB_1*PQ[a0]*QC_0*QC_1*QD_0*QD_1*QD_y) + delta[b1][g0]*(-PA_0*PB_0*QC_0*QC_1*QD_0*QD_1*QD_y + PA_0*PQ[b0]*QC_0*QC_1*QD_0*QD_1*QD_y + PB_0*PQ[a0]*QC_0*QC_1*QD_0*QD_1*QD_y)

                    )


                );

        ERIs[threadIdx.y][threadIdx.x] += eri_ijkl * dd_mat_D[kl] * kl_factor;

    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < pd_prim_pair_count_local))
    {
        double hess_il_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM; n++)
        {
            hess_il_xy += ERIs[n][threadIdx.x];
        }

        atomicAdd(
            hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + i] * natoms + atom_idx_l,
            hess_il_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }

    __syncthreads();

    }
}

__global__ void __launch_bounds__(TILE_SIZE_J)
computeCoulombHessianPDDD_IL_4(double*         hess_xy,
                               double*         hess_yx,
                               const uint32_t  hess_cart_ind_0,
                               const uint32_t  hess_cart_ind_1,
                               const double    prefac_coulomb,
                               const double*   p_prim_info,
                               const uint32_t  p_prim_count,
                               const double*   d_prim_info,
                               const uint32_t  d_prim_count,
                               const double*   pd_mat_D_local,
                               const double*   dd_mat_D,
                               const double*   pd_mat_Q_local,
                               const double*   dd_mat_Q,
                               const uint32_t* pd_first_inds_local,
                               const uint32_t* pd_second_inds_local,
                               const double*   pd_pair_data_local,
                               const uint32_t  pd_prim_pair_count_local,
                               const uint32_t* dd_first_inds,
                               const uint32_t* dd_second_inds,
                               const double*   dd_pair_data,
                               const uint32_t  dd_prim_pair_count,
                               const uint32_t* prim_cart_ao_to_atom_inds,
                               const uint32_t  natoms,
                               const uint32_t* d_kl_inds_for_atom_l,
                               const uint32_t* d_kl_counts_for_atom_l,
                               const uint32_t* d_kl_displs_for_atom_l,
                               const uint32_t  s_prim_count,
                               const double*   boys_func_table,
                               const double*   boys_func_ft,
                               const double    eri_threshold)
{
    // each thread row scans over [ij|??] and sum up to a primitive J matrix element
    // J. Chem. Theory Comput. 2009, 5, 4, 1004-1015

    __shared__ double   ERIs[TILE_DIM][TILE_DIM + 1];
    __shared__ uint32_t d_cart_inds[6][2];
    __shared__ double   delta[3][3];
    __shared__ uint32_t g0, g1;

    const uint32_t ij = blockDim.x * blockIdx.x + threadIdx.x;

    double a_i, a_j, r_i[3], r_j[3], S_ij_00, S1, inv_S1, ij_factor_D;
    double PA_0, PB_0, PB_1, PA_x;
    uint32_t i, j, a0, b0, b1;

    ERIs[threadIdx.y][threadIdx.x] = 0.0;

    if ((threadIdx.y == 0) && (threadIdx.x == 0))
    {
        d_cart_inds[0][0] = 0; d_cart_inds[0][1] = 0;
        d_cart_inds[1][0] = 0; d_cart_inds[1][1] = 1;
        d_cart_inds[2][0] = 0; d_cart_inds[2][1] = 2;
        d_cart_inds[3][0] = 1; d_cart_inds[3][1] = 1;
        d_cart_inds[4][0] = 1; d_cart_inds[4][1] = 2;
        d_cart_inds[5][0] = 2; d_cart_inds[5][1] = 2;

        delta[0][0] = 1.0; delta[0][1] = 0.0; delta[0][2] = 0.0;
        delta[1][0] = 0.0; delta[1][1] = 1.0; delta[1][2] = 0.0;
        delta[2][0] = 0.0; delta[2][1] = 0.0; delta[2][2] = 1.0;

        g0 = hess_cart_ind_0;
        g1 = hess_cart_ind_1;
    }

    __syncthreads();

    if (ij < pd_prim_pair_count_local)
    {
        i = pd_first_inds_local[ij];
        j = pd_second_inds_local[ij];

        a_i = p_prim_info[i / 3 + p_prim_count * 0];

        r_i[0] = p_prim_info[i / 3 + p_prim_count * 2];
        r_i[1] = p_prim_info[i / 3 + p_prim_count * 3];
        r_i[2] = p_prim_info[i / 3 + p_prim_count * 4];

        a_j = d_prim_info[j / 6 + d_prim_count * 0];

        r_j[0] = d_prim_info[j / 6 + d_prim_count * 2];
        r_j[1] = d_prim_info[j / 6 + d_prim_count * 3];
        r_j[2] = d_prim_info[j / 6 + d_prim_count * 4];

        S1 = a_i + a_j;
        inv_S1 = 1.0 / S1;

        S_ij_00 = pd_pair_data_local[ij];

        ij_factor_D = 2.0 * pd_mat_D_local[ij];

        PA_x = (a_j  * inv_S1) * (r_j[g0] - r_i[g0]);

        a0 = i % 3;
        b0 = d_cart_inds[j % 6][0];
        b1 = d_cart_inds[j % 6][1];

        PA_0 = (a_j  * inv_S1) * (r_j[a0] - r_i[a0]);
        PB_0 = (-a_i * inv_S1) * (r_j[b0] - r_i[b0]);
        PB_1 = (-a_i * inv_S1) * (r_j[b1] - r_i[b1]);

    }

    for (uint32_t atom_idx_l = 0; atom_idx_l < natoms; atom_idx_l++)
    {

    ERIs[threadIdx.y][threadIdx.x] = 0.0;

    __syncthreads();

    const auto kl_pair_count = d_kl_counts_for_atom_l[atom_idx_l];
    const auto kl_pair_displ = d_kl_displs_for_atom_l[atom_idx_l];

    for (uint32_t m = 0; m < (kl_pair_count + TILE_DIM - 1) / TILE_DIM; m++)
    {
        const uint32_t kl_raw = m * TILE_DIM + threadIdx.y;

        if (kl_raw >= kl_pair_count) break;

        // note non-coalesced read wrt kl
        const uint32_t kl = d_kl_inds_for_atom_l[kl_pair_displ + kl_raw];

        if ((kl >= dd_prim_pair_count) || (ij >= pd_prim_pair_count_local) || (fabs(pd_mat_Q_local[ij] * dd_mat_Q[kl] * dd_mat_D[kl]) <= eri_threshold))
        {
            break;
        }

        const auto k = dd_first_inds[kl];
        const auto l = dd_second_inds[kl];

        const auto a_k = d_prim_info[k / 6 + d_prim_count * 0];

        const double r_k[3] = {d_prim_info[k / 6 + d_prim_count * 2],
                               d_prim_info[k / 6 + d_prim_count * 3],
                               d_prim_info[k / 6 + d_prim_count * 4]};

        const auto a_l = d_prim_info[l / 6 + d_prim_count * 0];

        const double r_l[3] = {d_prim_info[l / 6 + d_prim_count * 2],
                               d_prim_info[l / 6 + d_prim_count * 3],
                               d_prim_info[l / 6 + d_prim_count * 4]};

        const auto S_kl_00 = dd_pair_data[kl];

        const auto c0 = d_cart_inds[k % 6][0];
        const auto c1 = d_cart_inds[k % 6][1];
        const auto d0 = d_cart_inds[l % 6][0];
        const auto d1 = d_cart_inds[l % 6][1];

        // J. Chem. Phys. 84, 3963-3974 (1986)

        const auto S2 = a_k + a_l;

        const auto inv_S2 = 1.0 / S2;
        const auto inv_S4 = 1.0 / (S1 + S2);

        const double PQ[3] = {(a_k * r_k[0] + a_l * r_l[0]) * inv_S2 - (a_i * r_i[0] + a_j * r_j[0]) * inv_S1,
                              (a_k * r_k[1] + a_l * r_l[1]) * inv_S2 - (a_i * r_i[1] + a_j * r_j[1]) * inv_S1,
                              (a_k * r_k[2] + a_l * r_l[2]) * inv_S2 - (a_i * r_i[2] + a_j * r_j[2]) * inv_S1};

        const auto r2_PQ = PQ[0] * PQ[0] + PQ[1] * PQ[1] + PQ[2] * PQ[2];

        const auto Lambda = sqrt(4.0 * S1 * S2 * MATH_CONST_INV_PI * inv_S4);

        double F9_t[3];

        gpu::computeBoysFunction(F9_t, S1 * S2 * inv_S4 * r2_PQ, 2, boys_func_table, boys_func_ft);

        const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
        const auto QC_1 = (a_l * inv_S2) * (r_l[c1] - r_k[c1]);
        const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
        const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

        const auto QD_y = (-a_k * inv_S2) * (r_l[g1] - r_k[g1]);

        double kl_factor = (static_cast<double>(k != l) + 1.0);

        // mu-sigma hessian

        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[1] * S2 * inv_S1 * inv_S4 * a_i * (

                        +delta[a0][b0]*delta[d0][g1]*(PA_x*PB_1*QC_0*QC_1*QD_1 - PA_x*PQ[b1]*QC_0*QC_1*QD_1 - PB_1*PQ[g0]*QC_0*QC_1*QD_1) + delta[a0][b0]*delta[d1][g1]*(PA_x*PB_1*QC_0*QC_1*QD_0 - PA_x*PQ[b1]*QC_0*QC_1*QD_0 - PB_1*PQ[g0]*QC_0*QC_1*QD_0) + delta[a0][b1]*delta[d0][g1]*(PA_x*PB_0*QC_0*QC_1*QD_1 - PA_x*PQ[b0]*QC_0*QC_1*QD_1 - PB_0*PQ[g0]*QC_0*QC_1*QD_1) + delta[a0][b1]*delta[d1][g1]*(PA_x*PB_0*QC_0*QC_1*QD_0 - PA_x*PQ[b0]*QC_0*QC_1*QD_0 - PB_0*PQ[g0]*QC_0*QC_1*QD_0) + delta[a0][g0]*delta[d0][g1]*(PB_0*PB_1*QC_0*QC_1*QD_1 - PB_0*PQ[b1]*QC_0*QC_1*QD_1 - PB_1*PQ[b0]*QC_0*QC_1*QD_1) + delta[a0][g0]*delta[d1][g1]*(PB_0*PB_1*QC_0*QC_1*QD_0 - PB_0*PQ[b1]*QC_0*QC_1*QD_0 - PB_1*PQ[b0]*QC_0*QC_1*QD_0) + delta[b0][b1]*delta[d0][g1]*(PA_0*PA_x*QC_0*QC_1*QD_1 - PA_0*PQ[g0]*QC_0*QC_1*QD_1 - PA_x*PQ[a0]*QC_0*QC_1*QD_1) + delta[b0][b1]*delta[d1][g1]*(PA_0*PA_x*QC_0*QC_1*QD_0 - PA_0*PQ[g0]*QC_0*QC_1*QD_0 - PA_x*PQ[a0]*QC_0*QC_1*QD_0) + delta[b0][g0]*delta[d0][g1]*(PA_0*PB_1*QC_0*QC_1*QD_1 - PA_0*PQ[b1]*QC_0*QC_1*QD_1 - PB_1*PQ[a0]*QC_0*QC_1*QD_1) + delta[b0][g0]*delta[d1][g1]*(PA_0*PB_1*QC_0*QC_1*QD_0 - PA_0*PQ[b1]*QC_0*QC_1*QD_0 - PB_1*PQ[a0]*QC_0*QC_1*QD_0) + delta[b1][g0]*delta[d0][g1]*(PA_0*PB_0*QC_0*QC_1*QD_1 - PA_0*PQ[b0]*QC_0*QC_1*QD_1 - PB_0*PQ[a0]*QC_0*QC_1*QD_1) + delta[b1][g0]*delta[d1][g1]*(PA_0*PB_0*QC_0*QC_1*QD_0 - PA_0*PQ[b0]*QC_0*QC_1*QD_0 - PB_0*PQ[a0]*QC_0*QC_1*QD_0)

                    )

                    + F9_t[1] * S2 * inv_S1 * inv_S4 * a_l * (

                        +QC_0*QC_1*QD_0*QD_1*QD_y*delta[a0][g0]*delta[b0][b1]

