                        +(-PA_0*PA_x*PQ[c0] - PA_0*PA_x*QC_0)*(delta[b0][c1]*delta[b1][d0]*delta[d1][g1] + delta[b0][c1]*delta[b1][d1]*delta[d0][g1] + delta[b0][c1]*delta[b1][g1]*delta[d0][d1] + delta[b0][d0]*delta[b1][c1]*delta[d1][g1] + delta[b0][d0]*delta[b1][d1]*delta[c1][g1] + delta[b0][d0]*delta[b1][g1]*delta[c1][d1] + delta[b0][d1]*delta[b1][c1]*delta[d0][g1] + delta[b0][d1]*delta[b1][d0]*delta[c1][g1] + delta[b0][d1]*delta[b1][g1]*delta[c1][d0] + delta[b0][g1]*delta[b1][c1]*delta[d0][d1] + delta[b0][g1]*delta[b1][d0]*delta[c1][d1] + delta[b0][g1]*delta[b1][d1]*delta[c1][d0]) + (-PA_0*PA_x*PQ[c1] - PA_0*PA_x*QC_1)*(delta[b0][c0]*delta[b1][d0]*delta[d1][g1] + delta[b0][c0]*delta[b1][d1]*delta[d0][g1] + delta[b0][c0]*delta[b1][g1]*delta[d0][d1] + delta[b0][d0]*delta[b1][c0]*delta[d1][g1] + delta[b0][d0]*delta[b1][d1]*delta[c0][g1] + delta[b0][d0]*delta[b1][g1]*delta[c0][d1] + delta[b0][d1]*delta[b1][c0]*delta[d0][g1] + delta[b0][d1]*delta[b1][d0]*delta[c0][g1] + delta[b0][d1]*delta[b1][g1]*delta[c0][d0] + delta[b0][g1]*delta[b1][c0]*delta[d0][d1] + delta[b0][g1]*delta[b1][d0]*delta[c0][d1] + delta[b0][g1]*delta[b1][d1]*delta[c0][d0]) + (-PA_0*PA_x*PQ[d0] - PA_0*PA_x*QD_0)*(delta[b0][c0]*delta[b1][c1]*delta[d1][g1] + delta[b0][c0]*delta[b1][d1]*delta[c1][g1] + delta[b0][c0]*delta[b1][g1]*delta[c1][d1] + delta[b0][c1]*delta[b1][c0]*delta[d1][g1] + delta[b0][c1]*delta[b1][d1]*delta[c0][g1] + delta[b0][c1]*delta[b1][g1]*delta[c0][d1] + delta[b0][d1]*delta[b1][c0]*delta[c1][g1] + delta[b0][d1]*delta[b1][c1]*delta[c0][g1] + delta[b0][d1]*delta[b1][g1]*delta[c0][c1] + delta[b0][g1]*delta[b1][c0]*delta[c1][d1] + delta[b0][g1]*delta[b1][c1]*delta[c0][d1] + delta[b0][g1]*delta[b1][d1]*delta[c0][c1]) + (-PA_0*PA_x*PQ[d1] - PA_0*PA_x*QD_1)*(delta[b0][c0]*delta[b1][c1]*delta[d0][g1] + delta[b0][c0]*delta[b1][d0]*delta[c1][g1] + delta[b0][c0]*delta[b1][g1]*delta[c1][d0] + delta[b0][c1]*delta[b1][c0]*delta[d0][g1] + delta[b0][c1]*delta[b1][d0]*delta[c0][g1] + delta[b0][c1]*de