] + delta[a0][c1]*delta[b0][b1]*delta[c0][d0]*delta[d1][g1] + delta[a0][c1]*delta[b0][b1]*delta[c0][d1]*delta[d0][g1] + delta[a0][d0]*delta[b0][b1]*delta[c0][c1]*delta[d1][g1] + delta[a0][d1]*delta[b0][b1]*delta[c0][c1]*delta[d0][g1])

