][g0])*(PB_0*PQ[c0]*PQ[c1]*QD_0*QD_1 + PB_0*PQ[c0]*PQ[d0]*QC_1*QD_1 + PB_0*PQ[c0]*PQ[d1]*QC_1*QD_0 + PB_0*PQ[c1]*PQ[d0]*QC_0*QD_1 + PB_0*PQ[c1]*PQ[d1]*QC_0*QD_0 + PB_0*PQ[d0]*PQ[d1]*QC_0*QC_1) + (delta[b0][b1]*delta[c0][g0] + delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0])*(PA_0*PQ[c1]*PQ[d0]*QD_1*QD_y + PA_0*PQ[c1]*PQ[d1]*QD_0*QD_y + PA_0*PQ[c1]*PQ[g1]*QD_0*QD_1 + PA_0*PQ[d0]*PQ[d1]*QC_1*QD_y + PA_0*PQ[d0]*PQ[g1]*QC_1*QD_1 + PA_0*PQ[d1]*PQ[g1]*QC_1*QD_0) + (delta[b0][b1]*delta[c1][g0] + delta[b0][c1]*delta[b1][g0] + delta[b0][g0]*delta[b1][c1])*(PA_0*PQ[c0]*PQ[d0]*QD_1*QD_y + PA_0*PQ[c0]*PQ[d1]*QD_0*QD_y + PA_0*PQ[c0]*PQ[g1]*QD_0*QD_1 + PA_0*PQ[d0]*PQ[d1]*QC_0*QD_y + PA_0*PQ[d0]*PQ[g1]*QC_0*QD_1 + PA_0*PQ[d1]*PQ[g1]*QC_0*QD_0) + (delta[b0][b1]*delta[d0][g0] + delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0])*(PA_0*PQ[c0]*PQ[c1]*QD_1*QD_y + PA_0*PQ[c0]*PQ[d1]*QC_1*QD_y + PA_0*PQ[c0]*PQ[g1]*QC_1*QD_1 + PA_0*PQ[c1]*PQ[d1]*QC_0*QD_y + PA_0*PQ[c1]*PQ[g1]*QC_0*QD_1 + PA_0*PQ[d1]*PQ[g1]*QC_0*QC_1) + (delta[b0][b1]*delta[d1][g0] + delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1])*(PA_0*PQ[c0]*PQ[c1]*QD_0*QD_y + PA_0*PQ[c0]*PQ[d0]*QC_1*QD_y + PA_0*PQ[c0]*PQ[g1]*QC_1*QD_0 + PA_0*PQ[c1]*PQ[d0]*QC_0*QD_y + PA_0*PQ[c1]*PQ[g1]*QC_0*QD_0 + PA_0*PQ[d0]*PQ[g1]*QC_0*QC_1) + (delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])*(PA_0*PQ[c0]*PQ[c1]*QD_0*QD_1 + PA_0*PQ[c0]*PQ[d0]*QC_1*QD_1 + PA_0*PQ[c0]*PQ[d1]*QC_1*QD_0 + PA_0*PQ[c1]*PQ[d0]*QC_0*QD_1 + PA_0*PQ[c1]*PQ[d1]*QC_0*QD_0 + PA_0*PQ[d0]*PQ[d1]*QC_0*QC_1)

