                        -PA_0*PQ[c0]*PQ[c1]*(delta[b0][b1]*delta[d0][g0]*delta[d1][g1] + delta[b0][b1]*delta[d0][g1]*delta[d1][g0] + delta[b0][d0]*delta[b1][g0]*delta[d1][g1] + delta[b0][d1]*delta[b1][g0]*delta[d0][g1] + delta[b0][g0]*delta[b1][d0]*delta[d1][g1] + delta[b0][g0]*delta[b1][d1]*delta[d0][g1]) - PB_0*PQ[c0]*PQ[c1]*(delta[a0][b1]*delta[d0][g0]*delta[d1][g1] + delta[a0][b1]*delta[d0][g1]*delta[d1][g0] + delta[a0][d0]*delta[b1][g0]*delta[d1][g1] + delta[a0][d1]*delta[b1][g0]*delta[d0][g1] + delta[a0][g0]*delta[b1][d0]*delta[d1][g1] + delta[a0][g0]*delta[b1][d1]*delta[d0][g1]) - PB_1*PQ[c0]*PQ[c1]*(delta[a0][b0]*delta[d0][g0]*delta[d1][g1] + delta[a0][b0]*delta[d0][g1]*delta[d1][g0] + delta[a0][d0]*delta[b0][g0]*delta[d1][g1] + delta[a0][d1]*delta[b0][g0]*delta[d0][g1] + delta[a0][g0]*delta[b0][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][d1]*delta[d0][g1]) - PB_x*PQ[c0]*PQ[c1]*(delta[a0][b0]*delta[b1][d0]*delta[d1][g1] + delta[a0][b0]*delta[b1][d1]*delta[d0][g1] + delta[a0][b1]*delta[b0][d0]*delta[d1][g1] + delta[a0][b1]*delta[b0][d1]*delta[d0][g1] + delta[a0][d0]*delta[b0][b1]*delta[d1][g1] + delta[a0][d1]*delta[b0][b1]*delta[d0][g1])

