 + delta[b1][g0]*delta[d0][d1]*(PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*QD_y + PQ[a0]*PQ[b0]*PQ[c0]*PQ[g1]*QC_1 + PQ[a0]*PQ[b0]*PQ[c0]*QC_1*QD_y + PQ[a0]*PQ[b0]*PQ[c1]*PQ[g1]*QC_0 + PQ[a0]*PQ[b0]*PQ[c1]*QC_0*QD_y + PQ[a0]*PQ[b0]*PQ[g1]*QC_0*QC_1) + delta[b1][g0]*delta[d0][g1]*(PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*QD_1 + PQ[a0]*PQ[b0]*PQ[c0]*PQ[d1]*QC_1 + PQ[a0]*PQ[b0]*PQ[c0]*QC_1*QD_1 + PQ[a0]*PQ[b0]*PQ[c1]*PQ[d1]*QC_0 + PQ[a0]*PQ[b0]*PQ[c1]*QC_0*QD_1 + PQ[a0]*PQ[b0]*PQ[d1]*QC_0*QC_1) + delta[b1][g0]*delta[d1][g1]*(PQ[a0]*PQ[b0]*PQ[c0]*PQ[c1]*QD_0 + PQ[a0]*PQ[b0]*PQ[c0]*PQ[d0]*QC_1 + PQ[a0]*PQ[b0]*PQ[c0]*QC_1*QD_0 + PQ[a0]*PQ[b0]*PQ[c1]*PQ[d0]*QC_0 + PQ[a0]*PQ[b0]*PQ[c1]*QC_0*QD_0 + PQ[a0]*PQ[b0]*PQ[d0]*QC_0*QC_1)

